(window.EX_CHUNKS=window.EX_CHUNKS||{})["b45"]={"橡皮":[["这块橡皮擦得真干净。","بۇ ئۆچۈرگۈچ بەك تازا ئۆچۈردى.","bu öchürgüch bek taza öchürdi."]],"车库":[["我们把车停在了地下车库。","بىز ماشىنىنى يەر ئاستى ماشىنا توختىتىش ئورنىغا توختاتتۇق.","biz mashinini yer asti mashina toxtitish ornigha toxtattuq."]],"变故":[["家中突生变故，让他不得不提前返乡。","ئائىلىسىدە تۇيۇقسىز بىر ئىش يۈز بېرىپ، ئۇنى ۋاقتىدىن بۇرۇن يۇرتىغا قايتىشقا مەجبۇر قىلدى.","ailiside tuyuqsiz bir ish yüz bérip, uni waqtidin burun yurtigha qaytishqa mejbur qildi."]],"娇气":[["这孩子从小娇气，什么事都要人帮着做。","بۇ بالا كىچىكىدىنلا نازۇك بولۇپ، ھەممە ئىشتا كىشىلەرنىڭ ياردەم قىلىشىنى تەلەپ قىلىدۇ.","bu bala kichikidinla nazuk bolup, hemme ishta kishilerning yardem qilishini telep qilidu."]],"起哄":[["看到小丑表演，孩子们都起哄大笑。","مەسخىرە ئويۇنىنى كۆرۈپ، بالىلارنىڭ ھەممىسى ۋاراڭ-چۇرۇڭ قىلىپ كۈلۈشتى.","mesxire oyunini körüp, balilarning hemmisi warang-churung qilip külüshti."]],"伭":[["伭妙的手法令人惊叹。","ئۇنىڭ ماھىر ئۇسۇلى كىشىنى ھەيران قالدۇرىدۇ.","uning mahir usuli kishini heyran qalduridu."]],"嚭":[["他“嚭”地一声倒在了地上。","ئۇ «گۈپ» ئېتىپ يەرگە يىقىلدى.","u «güp» étip yerge yiqildi."]],"妭":[["小妭在画画。","شياوبا رەسىم سىزىۋاتىدۇ.","shyaoba resim siziwatidu."]],"孭":[["她孭着行李走了很远的路。","ئۇ يۈكىنى كۆتۈرۈپ ئۇزۇن يول ماڭدى.","u yükini kötürüp uzun yol mangdi."]],"慭":[["他慭然面对挑战，毫不畏惧。","ئۇ خىرىسلارغا مەردانىلىك بىلەن يۈزلەندى، ھېچقانداق قورقمىدى.","u xirislargha merdanilik bilen yüzlendi, héchqandaq qorqmidi."]],"戭":[["戭字多用于地名，如“戭城”。","«يەن» خېتى كۆپىنچە يەر ناملىرىدا ئىشلىتىلىدۇ، مەسىلەن «يەنچېڭ».","«yen» xéti köpinche yer namlirida ishlitilidu, mesilen «yenchéng»."]],"桭":[["桭木常用于制作家具。","چېن دەرىخى ئادەتتە ئۆي جاھازىسى ياساشتا ئىشلىتىلىدۇ.","chén derixi adette öy jahazisi yasashta ishlitilidu."]],"猭":[["猭的叫声像狗。","بۇرغىنىڭ ئاۋازى ئىتنىڭكىگە ئوخشايدۇ.","burghining awazi itningkige oxshaydu."]],"瞭":[["瞭望塔上的士兵警惕地观察着四周。","كۆزىتىش مۇنارىدىكى ئەسكەرلەر ھوشيارلىق بىلەن ئەتراپنى كۆزىتىپ تۇردى.","közitish munaridiki eskerler hoshyarliq bilen etrapni közitip turdi."]],"芭":[["芭蕉树的叶子很大。","بانان دەرىخىنىڭ يوپۇرمىقى ئىنتايىن چوڭ.","banan derixining yopurmiqi intayin chong."]],"筭":[["筭是一种历史悠久的计算工具。","سۈەن قەدىمىي تارىخقا ئىگە ھېسابلاش قورالىدۇر.","süen qedimiy tarixqa ige hésablash qoralidur."]],"豭":[["豭是一种古老的猪品种。","جا قەدىمىي بىر خىل چوشقا تۈرى.","ja qedimiy bir xil choshqa türi."]],"鼭":[["鼭鱼生活在深海中。","قۇمۇچبېلىق چوڭقۇر دېڭىزدا ياشايدۇ.","qumuchbéliq chongqur déngizda yashaydu."]],"一小部分":[["只有一小部分人参加了活动。","پەقەت كىچىك بىر قىسىم كىشىلا پائالىيەتكە قاتناشتى.","peqet kichik bir qisim kishila paaliyetke qatnashti."]],"一改故辙":[["公司一改故辙，开始推行新的管理方法。","شىركەت ئەسكى ئادەتنى ئۆزگەرتىپ، يېڭى باشقۇرۇش ئۇسۇلىنى يولغا قويۇشقا باشلىدى.","shirket eski adetni özgertip, yéngi bashqurush usulini yolgha qoyushqa bashlidi."]],"一物降一物":[["正所谓一物降一物，总有办法。","دېيىلگەندەك، ھەر بىر نەرسىنىڭ بىر بېسىپ تۇرىدىغىنى بار، چارە تېپىلىدۇ.","déyilgendek, her bir nersining bir bésip turidighini bar, chare tépilidu."]],"一等奖":[["他赢得了比赛的一等奖。","ئۇ مۇسابىقىنىڭ بىرىنچى دەرىجىلىك مۇكاپاتىنى يۇتتى.","u musabiqining birinchi derijilik mukapatini yutti."]],"一级头":[["他是一级头目。","ئۇ بىرىنچى دەرىجىلىك باشلىق.","u birinchi derijilik bashliq."]],"三元醇":[["这种化学物质属于三元醇类。","بۇ خىل خىمىيىلىك ماددا ئۈچ ئاتوملۇق ئالكوھول تۈرىگە كىرىدۇ.","bu xil ximiyilik madda üch atomluq alkohol türige kiridu."]],"三秒胶":[["三秒胶是一种快速固化的胶水。","ئۈچ سېكۇنتلىق يېلىم تېز قاتتىقلىشىدىغان بىر يېلىم.","üch sékuntliq yélim téz qattiqlishidighan bir yélim."]],"三跪九叩":[["古代礼仪要求三跪九叩。","قەدىمكى زامان مۇراسىمى ئۈچ قېتىم تىزلىنىپ توققۇز قېتىم باش ئۇرۇشنى تەلەپ قىلاتتى.","qedimki zaman murasimi üch qétim tizlinip toqquz qétim bash urushni telep qilatti."]],"一点一滴":[["成功需要一点一滴的积累。","مۇۋەپپەقىيەت ئاز-ئازدىن توپلىنىشقا موھتاج.","muweppeqiyet az-azdin toplinishqa mohtaj."]],"不明确":[["说明不明确。","چۈشەندۈرۈش ئېنىق ئەمەس.","chüshendürüsh éniq emes."]],"不会":[["他根本不会游泳。","ئۇ ئەسلا ئۈزۈش بىلمەيدۇ.","u esla üzüsh bilmeydu."]],"不用客气":[["你不用客气，这是我应该做的。","سىز تەكەللۇپ قىلماڭ، بۇ مېنىڭ قىلىشقا تېگىشلىك ئىشىم.","siz tekellup qilmang, bu méning qilishqa tégishlik ishim."]],"丙烯酸酯":[["丙烯酸酯常用于涂料中。","ئاكرىل كىسلاتا ئېستېرى ئادەتتە سىرلاردا ئىشلىتىلىدۇ.","akril kislata éstéri adette sirlarda ishlitilidu."]],"并口":[["这个设备有两个并口。","بۇ ئۈسكۈنىنىڭ ئىككى پاراللېل ئېغىزى بار.","bu üskünining ikki parallél éghizi bar."]],"中区":[["中区是城市的商业中心。","ئوتتۇرا رايون شەھەرنىڭ سودا مەركىزى.","ottura rayon sheherning soda merkizi."]],"中南海":[["中南海是中国的政治中心。","جۇڭنەنھەي جۇڭگونىڭ سىياسىي مەركىزى.","jungnenhey junggoning siyasiy merkizi."]],"中国话":[["他用流利的中国话与朋友交流。","ئۇ راۋان جۇڭگوچە سۆزلەش ئارقىلىق دوستلىرى بىلەن ئالاقە قىلدى.","u rawan junggoche sözlesh arqiliq dostliri bilen alaqe qildi."]],"中央财经大学":[["中央财经大学培养财经人才。","مەركىزىي مالىيە-ئىقتىساد ئۇنىۋېرسىتېتى مالىيە-ئىقتىساد ئىختىساسلىرىنى يېتىشتۈرىدۇ.","merkiziy maliye-iqtisad uniwérsitéti maliye-iqtisad ixtisaslirini yétishtüridu."]],"中江县":[["中江县位于四川省的西南部。","جۇڭجياڭ ناھىيىسى سىچۇەن ئۆلكىسىنىڭ جەنۇبىي غەربىي قىسمىدا جايلاشقان.","jungjyang nahiyisi sichuen ölkisining jenubiy gherbiy qismida jaylashqan."]],"中牟县":[["中牟县位于河南省中部。","جۇڭمۇ ناھىيىسى خېنەن ئۆلكىسىنىڭ ئوتتۇرىسىدا جايلاشقان.","jungmu nahiyisi xénen ölkisining otturisida jaylashqan."]],"事半功倍":[["新方法让工作事半功倍。","يېڭى ئۇسۇل ئىشنىڭ ئۈنۈمىنى ئىككى ھەسسە ئاشۇردى.","yéngi usul ishning ünümini ikki hesse ashurdi."]],"二奶专家":[["二奶专家指的是擅长处理情感问题的人。","ئىككىنچى خوتۇن مۇتەخەسسىسى ھېسسىيات مەسىلىلىرىنى بىر تەرەپ قىلىشقا ماھىر كىشىلەرنى كۆرسىتىدۇ.","ikkinchi xotun mutexessisi héssiyat mesililirini bir terep qilishqa mahir kishilerni körsitidu."]],"五分熟":[["这块牛排五分熟，口感刚刚好。","بۇ بېفستېيك بەش قاتلام پىشقان، تەمى دەل مۇۋاپىق.","bu béfstéyk besh qatlam pishqan, temi del muwapiq."]],"五十":[["他今年已经五十岁了，经验丰富。","ئۇ بۇ يىل ئاللىبۇرۇن ئەللىك ياشقا كىردى، تەجرىبىسى مول.","u bu yil alliburun ellik yashqa kirdi, tejribisi mol."]],"交保释放":[["交保释放是常见的司法程序。","كاپالەت بىلەن قويۇپ بېرىش ئادەتتىكى سوت تەرتىپى.","kapalet bilen qoyup bérish adettiki sot tertipi."]],"亚利桑纳州":[["亚利桑纳州是美国西南部的一个州。","ئارىزونا شتاتى ئامېرىكىنىڭ جەنۇبىي غەربىدىكى بىر شتاتتۇر.","arizona shtati amérikining jenubiy gherbidiki bir shtattur."]],"人民银行":[["人民银行负责国家货币发行。","خەلق بانكىسى دۆلەت پۇل-تەڭگىسىنى تارقىتىشقا مەسئۇلدۇر.","xelq bankisi dölet pul-tenggisini tarqitishqa mes'uldur."]],"人民民主专政":[["人民民主专政是国体。","خەلق دېموكراتىك دىكتاتۇرىسى دۆلەت تۈزۈمى.","xelq démokratik diktaturisi dölet tüzümi."]],"人力资源":[["企业需要优化人力资源配置。","كارخانا ئادەم كۈچى بايلىقىنى تەقسىملەشنى ياخشىلاشقا ئېھتىياجلىق.","karxana adem küchi bayliqini teqsimleshni yaxshilashqa éhtiyajliq."]],"今古文":[["今古文是古代汉语的重要研究内容。","بۈگۈنكى ۋە قەدىمكى يازما ئەدەبىيات قەدىمكى خەنزۇ تىلىنىڭ مۇھىم تەتقىقات مەزمۇنىدۇر.","bügünki we qedimki yazma edebiyat qedimki xenzu tilining muhim tetqiqat mezmunidur."]],"代数":[["数学中的代数涉及变量和方程。","ماتېماتىكىدىكى ئالگېبرا ئۆزگەرگۈچى ۋە تەڭلىمىلەرنى ئۆز ئىچىگە ئالىدۇ.","matématikidiki algébra özgergüchi we tenglimilerni öz ichige alidu."]],"以防":[["我们要做好防范，以防意外发生。","بىز ھەر خىل تاسادىپىي ئەھۋاللارنىڭ يۈز بېرىشىنىڭ ئالدىنى ئېلىش ئۈچۈن مۇداپىئە تەييارلىقىنى ياخشى قىلىشىمىز كېرەك.","biz her xil tasadipiy ehwallarning yüz bérishining aldini élish üchün mudapie teyyarliqini yaxshi qilishimiz kérek."]],"伯克利":[["伯克利音乐学院很有名。","بېركلى مۇزىكا ئىنستىتۇتى بەك داڭلىق.","bérkli muzika instituti bek dangliq."]],"仙女座":[["仙女座是一个遥远的星系。","ئاندرومېدا تارقاق بىر گالاكتىكا.","androméda tarqaq bir galaktika."]],"佛门":[["佛门向来以宽容和包容著称。","بۇددا دەرگاھى كەڭ قورساقلىق ۋە مۇرەسسە قىلىش بىلەن تونۇلغان.","budda dergahi keng qorsaqliq we muresse qilish bilen tonulghan."]],"佛骨":[["佛骨被供奉在专门的佛骨塔中。","بۇددا سۆڭىكى مەخسۇس بۇددا سۆڭەك مۇنارىدا ئاتاپ قويۇلغان.","budda söngiki mexsus budda söngek munarida atap qoyulghan."]],"何止":[["他不仅会唱歌，何止于此，还会跳舞。","ئۇ پەقەت ناخشا ئېيتىپلا قالماي، بۇنىڭدىن باشقا، ئۇسسۇل ئوينايدۇ.","u peqet naxsha éytipla qalmay, buningdin bashqa, ussul oynaydu."]],"余车":[["余车停在路边等待乘客。","قالغان ماشىنا يول بويىدا يولۇچىلارنى ساقلاپ توختىغان.","qalghan mashina yol boyida yoluchilarni saqlap toxtighan."]],"你真行":[["你真行，太棒了！","سەن ھەقىقەتەن قالتىس، بەك ياخشى!","sen heqiqeten qaltis, bek yaxshi!"]],"例题":[["这道例题难度适中。","بۇ مىسال مەسىلىنىڭ قىيىنلىق دەرىجىسى مۇۋاپىق.","bu misal mesilining qiyinliq derijisi muwapiq."]],"侃大山":[["他们坐在树下侃大山。","ئۇلار دەرەخ ئاستىدا ئولتۇرۇپ ۋاقىت ئۆتكۈزۈپ پاراڭلاشتى.","ular derex astida olturup waqit ötküzüp paranglashti."]],"信差":[["信差负责将信件准时送到收件人手中。","خەت تارقىتىغۇچى خەتلەرنى ۋاقتىدا خەت ئالغۇچىنىڭ قولىغا يەتكۈزۈشكە مەسئۇل.","xet tarqitighuchi xetlerni waqtida xet alghuchining qoligha yetküzüshke mes'ul."]],"候车":[["他在车站候车。","ئۇ بېكەتتە پويىز كۈتۈۋاتىدۇ.","u békette poyiz kütüwatidu."]],"倒替":[["他倒替朋友完成了任务，大家都很感激。","ئۇ دوستىنىڭ ئورنىغا ۋەزىپىنى تاماملاپ بەردى، كۆپچىلىك ئىنتايىن مىننەتدار بولدى.","u dostining ornigha wezipini tamamlap berdi, köpchilik intayin minnetdar boldi."]],"假摔":[["假摔的行为违背了体育精神。","ساختا يىقىلىش قىلمىشى تەنتەربىيە روھىغا خىلاپ.","saxta yiqilish qilmishi tenterbiye rohigha xilap."]],"偶蹄类":[["偶蹄类动物在生态系统中作用重要。","جۈپ تۇياقلىق ھايۋانلار ئېكولوگىيەلىك سىستېمىدا مۇھىم رول ئوينايدۇ.","jüp tuyaqliq haywanlar ékologiyelik sistémida muhim rol oynaydu."]],"值得品味":[["这道菜值得品味。","بۇ تائام تېتىپ كۆرۈشكە ئەرزىيدۇ.","bu taam tétip körüshke erziydu."]],"借酒浇愁":[["他借酒浇愁，喝得酩酊大醉。","ئۇ ھاراق ئىچىپ غەم-قايغۇسىنى باستى، ھەددىدىن زىيادە مەست بولۇپ قالدى.","u haraq ichip ghem-qayghusini basti, heddidin ziyade mest bolup qaldi."]],"传遍":[["好消息很快就传遍整个村庄。","خۇش خەۋەر پۈتۈن كەنتكە تېز تارقالدى.","xush xewer pütün kentke téz tarqaldi."]],"传种":[["植物通过传种繁殖。","ئۆسۈملۈكلەر ئۇرۇق تارقىتىش ئارقىلىق كۆپىيىدۇ.","ösümlükler uruq tarqitish arqiliq köpiyidu."]],"克里斯托弗":[["克里斯托弗是一位著名的探险家。","كرىستوفېر بىر داڭلىق تەكشۈرۈشچى.","kristofér bir dangliq tekshürüshchi."]],"全科医生":[["全科医生可以处理多种常见疾病。","ئومۇمىي تېببىي ئەمەلىيەت دوختۇرى كۆپ خىل كۆپ ئۇچرايدىغان كېسەللىكلەرنى داۋالاپ بېرەلەيدۇ.","omumiy tébbiy emeliyet doxturi köp xil köp uchraydighan késelliklerni dawalap béreleydu."]],"儿歌":[["这首儿歌朗朗上口。","بۇ بالىلار ناخشىسى ئېغىزدىن چۈشۈپ قالمايدۇ.","bu balilar naxshisi éghizdin chüshüp qalmaydu."]],"克拉克":[["克拉克是著名的物理学家。","كلارك مەشھۇر فىزىكا ئالىمى.","klark meshhur fizika alimi."]],"八疸":[["八疸是一种古代医学中的病症。","سەككىز سېرىقلىق قەدىمكى تېببىيەتتىكى بىر كېسەللىك.","sekkiz sériqliq qedimki tébbiyettiki bir késellik."]],"公共关系":[["公共关系处理得好。","ئاممىۋى مۇناسىۋەتلەر ياخشى بىر تەرەپ قىلىندى.","ammiwi munasiwetler yaxshi bir terep qilindi."]],"冒牌货":[["小心买到冒牌货。","يالغان ماركىلىق مال سېتىۋېلىشتىن ئېھتىيات قىلىڭ.","yalghan markiliq mal sétiwélishtin éhtiyat qiling."]],"冒风险":[["他们决定冒风险尝试新的方案。","ئۇلار خەتەرگە بېشىنى تىكىپ يېڭى پىلاننى سىناپ بېقىشنى قارار قىلدى.","ular xeterge béshini tikip yéngi pilanni sinap béqishni qarar qildi."]],"冤家对头":[["这两个团队是多年的冤家对头。","بۇ ئىككى گۇرۇپپا كۆپ يىللاردىن بېرى دۈشمەن.","bu ikki guruppa köp yillardin béri düshmen."]],"冤抑":[["古代冤抑案件多因证据不足。","قەدىمكى زاماندا ئەپسۇسلىككە تولغان ئىشلار كۆپىنچە دەلىل-ئىسپات يېتەرسىزلىكتىن كېلىپ چىققان.","qedimki zamanda epsuslikke tolghan ishlar köpinche delil-ispat yétersizliktin kélip chiqqan."]],"出产":[["这里出产优质水果。","بۇ يەردە ئەلا سۈپەتلىك مېۋىلەر ئىشلەپچىقىرىلىدۇ.","bu yerde ela süpetlik méwiler ishlepchiqirilidu."]],"出丧":[["他们正在出丧。","ئۇلار ئۆلۈم تەڭلىكىنى ئېلىپ چىقىۋاتىدۇ.","ular ölüm tenglikini élip chiqiwatidu."]],"分子化合物":[["分子化合物由多个原子组成。","مولېكۇلا بىرىكمىسى بىر قانچە ئاتومدىن تەركىب تاپىدۇ.","molékula birikmisi bir qanche atomdin terkib tapidu."]],"分数挂帅":[["分数挂帅容易导致教育失衡。","نومۇرنى ئاساس قىلىش مائارىپنىڭ تەڭپۇڭسىزلىنىشىگە ئاسان سەۋەب بولىدۇ.","nomurni asas qilish maaripning tengpungsizlinishige asan seweb bolidu."]],"冰坝":[["冰坝融化可能引发洪水。","مۇز بۆگىتى ئېرىسە سەل قەھرىتى كەلتۈرۈپ چىقىرىشى مۇمكىن.","muz bögiti érise sel qehriti keltürüp chiqirishi mumkin."]],"冰晶石":[["冰晶石是重要的工业原料。","مۇز كرىستاللىق تاش مۇھىم سانائەت خام ماتېرىيالى.","muz kristalliq tash muhim sanaet xam matériyali."]],"刮胡刀":[["这把刮胡刀锋利又耐用。","بۇ ئۇستۇرا ئۆتكۈر ھەم چىداملىق.","bu ustura ötkür hem chidamliq."]],"削价":[["商店宣布大幅削价促销。","دۇكان باھانى زور دەرىجىدە چۈشۈرۈپ سېتىشنى ئېلان قىلدى.","dukan bahani zor derijide chüshürüp sétishni élan qildi."]],"前脚":[["前脚沾了泥。","پۇتىغا لاي چاپلىشىپ قالدى.","putigha lay chapliship qaldi."]],"副翼":[["飞机的副翼用于调整飞行姿态。","ئايروپىلاننىڭ ياردەمچى قانىتى ئۇچۇش ھالىتىنى تەڭشەشكە ئىشلىتىلىدۇ.","ayropilanning yardemchi qaniti uchush halitini tengsheshke ishlitilidu."]],"副校长":[["副校长主持了学校的毕业典礼。","مۇئاۋىن مەكتەپ مۇدىرى مەكتەپنىڭ پۈتۈش تەنتەنىسىگە رىياسەتچىلىك قىلدى.","muawin mektep mudiri mektepning pütüsh tentenisige riyasetchilik qildi."]],"利辛县":[["利辛县位于安徽省。","لىشىن ناھىيىسى ئەنخۇي ئۆلكىسىدە جايلاشقان.","lishin nahiyisi enxuy ölkiside jaylashqan."]],"刘毅":[["刘毅是东汉名将。","لىۇ يى شەرقىي خەن دەۋرىدىكى مەشھۇر سەركەردە.","liu yi sherqiy xen dewridiki meshhur serkerde."]],"刘禅":[["刘禅是蜀汉后主，以懦弱闻名。","لىۇ شەن شۇ خەننىڭ كېيىنكى پادىشاھى بولۇپ، ئاجىزلىقى بىلەن تونۇلغان.","liu shen shu xenning kéyinki padishahi bolup, ajizliqi bilen tonulghan."]],"加值型网路":[["加值型网路能提升用户体验。","قىممەت قوشۇلغان تور ئىشلەتكۈچى تەجرىبىسىنى ياخشىلايدۇ.","qimmet qoshulghan tor ishletküchi tejribisini yaxshilaydu."]],"胜诉":[["他最终胜诉了。","ئۇ ئاخىرىدا دەۋادا غەلىبە قازاندى.","u axirida dewada ghelibe qazandi."]],"胜选":[["他成功胜选。","ئۇ مۇۋەپپەقىيەتلىك سايلاندى.","u muweppeqiyetlik saylandi."]],"勤俭节约":[["提倡勤俭节约。","ئىقتىسادچىللىق ۋە تېجەشچىلىكنى تەشەببۇس قىلىش كېرەك.","iqtisadchilliq we téjeshchilikni teshebbus qilish kérek."]],"动物性饲料":[["动物性饲料适合某些宠物食用。","ھايۋان خاراكتېرلىك يەم بەزى ئۆي ھايۋانلىرىغا ماس كېلىدۇ.","haywan xaraktérlik yem bezi öy haywanlirigha mas kélidu."]],"包在我身上":[["这事包在我身上！","بۇ ئىش مېنىڭ ئۈستۈمدە!","bu ish méning üstümde!"]],"化学能":[["化学反应可以释放化学能。","خىمىيىلىك رېئاكسىيە خىمىيىلىك ئېنېرگىيەنى قويۇپ بېرەلەيدۇ.","ximiyilik réaksiye ximiyilik énérgiyeni qoyup béreleydu."]],"匪盗":[["匪盗们经常在山林里出没。","قاراقچىلار دائىم تاغ-ئورمانلاردا ئۇچراپ تۇرىدۇ.","qaraqchilar daim tagh-ormanlarda uchrap turidu."]],"北部湾":[["北部湾是广西的重要港口。","شىمالىي قولتۇق گۇاڭشىنىڭ مۇھىم پورتى.","shimaliy qoltuq guangshining muhim porti."]],"北齐书":[["《北齐书》是记载北朝历史的重要典籍。","«شىمالىي چى تارىخى» شىمالىي سۇلالىلەر تارىخىنى خاتىرىلىگەن مۇھىم كلاسسىك ئەسەر.","«shimaliy chi tarixi» shimaliy sulaliler tarixini xatiriligen muhim klassik eser."]],"十项全能":[["十项全能是综合性的田径比赛。","ئون تۈرلۈك ھەممىنى قىلالايدىغانلار مۇسابىقىسى ئۇنىۋېرسال يېنىك ئاتلېتىكا مۇسابىقىسى.","on türlük hemmini qilalaydighanlar musabiqisi uniwérsal yénik atlétika musabiqisi."]],"南乔治亚岛和南桑威奇":[["南乔治亚岛和南桑威奇群岛位于南极洲附近。","جەنۇبىي جورجىيە ئارىلى ۋە جەنۇبىي ساندۋىچ ئاراللىرى ئانتاركتىدا ئەتراپىدا جايلاشقان.","jenubiy jorjiye arili we jenubiy sandwich aralliri antarktida etrapida jaylashqan."]],"南齐书":[["《南齐书》是记载南齐历史的史书。","«جەنۇبىي چى سۇلالىسى تارىخى» جەنۇبىي چى سۇلالىسى تارىخىنى خاتىرىلىگەن تارىخىي كىتاب.","«jenubiy chi sulalisi tarixi» jenubiy chi sulalisi tarixini xatiriligen tarixiy kitab."]],"博文":[["博文网站内容非常全面。","بوۋېن تور بېكىتىنىڭ مەزمۇنى ئىنتايىن ئومۇمىي.","bowén tor békitining mezmuni intayin omumiy."]],"博斯腾湖":[["博斯腾湖是新疆的大湖。","بوستېن كۆلى شىنجاڭدىكى چوڭ كۆل.","bostén köli shinjangdiki chong köl."]],"博闻强识":[["他记忆力惊人，博闻强识。","ئۇنىڭ ئەسلىگە قايتۇرۇش قابىلىيىتى ھەيران قالارلىق، كەڭ ئاڭلاپ كۈچلۈك ئەسلىدە تونۇيدۇ.","uning eslige qayturush qabiliyiti heyran qalarliq, keng anglap küchlük eslide tonuydu."]],"南极海":[["南极海环绕着南极洲的边缘。","جەنۇبىي قۇتۇپ دېڭىزى جەنۇبىي قۇتۇپ قىتئەسىنىڭ گىرۋەكلىرىنى ئوراپ تۇرىدۇ.","jenubiy qutup déngizi jenubiy qutup qit'esining girweklirini orap turidu."]],"印地语":[["印地语是印度的官方语言之一。","ھىندى تىلى ھىندىستاننىڭ رەسمىي تىللىرىدىن بىرى.","hindi tili hindistanning resmiy tilliridin biri."]],"印度人民党":[["印度人民党是主要政党。","ھىندىستان خەلق پارتىيىسى ئاساسلىق سىياسىي پارتىيە.","hindistan xelq partiyisi asasliq siyasiy partiye."]],"卵裂":[["卵裂是早期胚胎发育过程。","تۇخۇم پارچىلىنىشى دەسلەپكى ئېمبىرىيون تەرەققىيات جەريانىدۇر.","tuxum parchilinishi deslepki émbiriyon tereqqiyat jeryanidur."]],"半中腰":[["他正在半中腰休息，不能继续爬了。","ئۇ يېرىم يولدا دەم ئېلىۋاتىدۇ، داۋاملىق چىقالمايدۇ.","u yérim yolda dem éliwatidu, dawamliq chiqalmaydu."]],"口述":[["他口述了这段历史的经过。","ئۇ بۇ تارىخنىڭ جەريانىنى ئېغىز بىلەن سۆزلەپ بەردى.","u bu tarixning jeryanini éghiz bilen sözlep berdi."]],"只许州官放火，不许百姓点灯":[["只许州官放火，不许百姓点灯。","پەقەت ئەمەلدارلار ئوت يېقىشقا بولىدۇ، پۇقرالار چىراغ يېقىشقا بولمايدۇ.","peqet emeldarlar ot yéqishqa bolidu, puqralar chiragh yéqishqa bolmaydu."]],"可压缩":[["气体具有可压缩性。","گاز سىقىلىشچانلىققا ئىگە.","gaz siqilishchanliqqa ige."]],"古特雷斯":[["古特雷斯是联合国的秘书长。","گۇتېررېس بىرلەشمە دۆلەتلەر تەشكىلاتىنىڭ باش كاتىپىدۇر.","gutérrés birleshme döletler teshkilatining bash katipidur."]],"古坑":[["古坑是考古发现的重要地点。","قەدىمكى ئورەك ئارخېئولوگىيەلىك بايقاشلارنىڭ مۇھىم ئورنى.","qedimki orek arxéologiyelik bayqashlarning muhim orni."]],"台湾叶鼻蝠":[["台湾叶鼻蝠是台湾特有的珍稀蝙蝠物种。","تەيۋەن يوپۇرماق بۇرنى تەيۋەنگە خاس ناياب شەپەرەڭ تۈرى.","teywen yopurmaq burni teywenge xas nayab shepereng türi."]],"可控硅":[["可控硅用于调节电压。","كونترول قىلغىلى بولىدىغان كرېمنىي توك بېسىمىنى تەڭشەشتە ئىشلىتىلىدۇ.","kontrol qilghili bolidighan krémniy tok bésimini tengsheshte ishlitilidu."]],"反党":[["反党言论受到严厉批评。","پارتىيەگە قارشى سۆزلەر قاتتىق تەنقىد قىلىندى.","partiyege qarshi sözler qattiq tenqid qilindi."]],"司马辽太郎":[["司马辽太郎的历史小说写得引人入胜。","سىما لياۋتايروڭنىڭ تارىخىي رومانلىرى ئىنتايىن جەلپكار يېزىلغان.","sima lyawtayrongning tarixiy romanliri intayin jelpkar yézilghan."]],"合页":[["合页用于连接书页。","خېيە بېتى كىتاب بەتلىرىنى بىرلەشتۈرۈشكە ئىشلىتىلىدۇ.","xéye béti kitab betlirini birleshtürüshke ishlitilidu."]],"吉首":[["吉首是湖南省的一个地级市。","جىشو خۇنەن ئۆلكىسىنىڭ بىر ۋىلايەت دەرىجىلىك شەھىرى.","jisho xunen ölkisining bir wilayet derijilik shehiri."]],"吊具":[["吊具是用于吊装货物的工具。","ئاسما ئەسۋاب يۈك ئېسىش ئۈچۈن ئىشلىتىلىدىغان قورال.","asma eswab yük ésish üchün ishlitilidighan qoral."]],"吊卷":[["吊卷是一种传统的中国舞蹈动作。","ئاسما ئورام جۇڭگونىڭ ئەنئەنىۋى ئۇسسۇل ھەرىكىتى.","asma oram junggoning en'eniwi ussul herikiti."]],"吉祥物":[["吉祥物代表团队的精神。","بەلگە ئەتىمى كوماندىنىڭ روھىنى ئىپادىلەيدۇ.","belge etimi komandining rohini ipadileydu."]],"同仁堂":[["这家药店的同仁堂药材很出名。","بۇ دورىخانىنىڭ تۇڭرېنتاڭ دورا ماتېرىياللىرى بەك مەشھۇر.","bu dorixanining tungréntang dora matériyalliri bek meshhur."]],"同仇敌忾":[["面对外敌，大家同仇敌忾。","سىرتقى دۈشمەنگە قارشى ھەممەيلەن بىر نىيەتتە بولۇشى كېرەك.","sirtqi düshmenge qarshi hemmeylen bir niyette bolushi kérek."]],"吊起":[["起重机将货物吊起并运走。","كران يۈكنى ئېسىپ كۆتۈرۈپ يۆتكەيدۇ.","kran yükni ésip kötürüp yötkeydu."]],"吝啬鬼":[["他是个出了名的吝啬鬼。","ئۇ تونۇلغان بېخىلنىڭ بىرى.","u tonulghan béxilning biri."]],"吞咽困难":[["老人有严重的吞咽困难。","بوۋاينىڭ يۇتۇش قىيىنچىلىقى ئېغىر.","bowayning yutush qiyinchiliqi éghir."]],"合成洗涤剂":[["合成洗涤剂去污能力强。","سىنتېتىك يۇيۇش ماددىسىنىڭ كىر ئېلىش قابىلىيىتى كۈچلۈك.","sintétik yuyush maddisining kir élish qabiliyiti küchlük."]],"吴堡":[["吴堡位于陕西省的北部。","ۋۇبۇ شەنشى ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","wubu shenshi ölkisining shimalida jaylashqan."]],"告捷":[["部队传来告捷的消息，令人振奋。","قىسىمدىن غەلىبە خەۋىرى كەلدى، بۇ كىشىلەرنى روھلاندۇردى.","qisimdin ghelibe xewiri keldi, bu kishilerni rohlandurdi."]],"周穆王":[["周穆王曾西巡昆仑。","جوۋ مۇۋاڭ بىر ۋاقىت غەربكە يۈرۈش قىلىپ كۈنلۈنگە بارغان.","jow muwang bir waqit gherbke yürüsh qilip künlünge barghan."]],"哄诱":[["他用甜言蜜语哄诱她。","ئۇ تاتلىق سۆزلەر بىلەن ئۇنى ئالدىدى.","u tatliq sözler bilen uni aldidi."]],"名义账户":[["这是一个名义账户。","بۇ بىر ئىسىملىك ھېسابات.","bu bir isimlik hésabat."]],"名誉博士":[["他被授予名誉博士称号。","ئۇغا شەرەپلىك دوكتورلۇق ئۇنۋانى بېرىلدى.","ugha shereplik doktorluq unwani bérildi."]],"唐人街":[["唐人街是海外华人聚集的重要区域。","تاڭلار كوچىسى چەت ئەلدىكى جۇڭگولۇقلار توپلانغان مۇھىم رايون.","tanglar kochisi chet eldiki junggoluqlar toplanghan muhim rayon."]],"咧嘴":[["他咧嘴一笑，露出牙齿。","ئۇ چىشىنى ئېچىپ كۈلۈمسىرىدى.","u chishini échip külümsiridi."]],"咬牙":[["他咬牙坚持，没有放弃。","ئۇ چىشىنى چىشلەپ چىداپ، ۋاز كەچمىدى.","u chishini chishlep chidap, waz kechmidi."]],"商河":[["商河是一条重要的河流。","شاڭخې مۇھىم بىر دەريا.","shangxé muhim bir derya."]],"唐哀帝":[["唐哀帝是唐朝的末代皇帝。","تاڭ ئەي دى تاڭ سۇلالىسىنىڭ ئاخىرقى ئىمپېراتورى.","tang ey di tang sulalisining axirqi impératori."]],"唐顺宗":[["唐顺宗是唐朝的第七位皇帝。","تەڭشۇنزۇڭ تەڭ سۇلالىسىنىڭ يەتتىنچى ئىمپېراتورىدۇر.","tengshunzung teng sulalisining yettinchi impératoridur."]],"售完即止":[["商品售完即止，请尽快购买。","مال سېتىلىپ بولغاندىن كېيىن توختايدۇ، تېز سېتىۋېلىڭ.","mal sétilip bolghandin kéyin toxtaydu, téz sétiwéling."]],"唯命是从":[["他唯命是从，从不反抗。","ئۇ پەقەت بۇيرۇققا بويسۇنىدۇ، ھەرگىز قارشىلىق كۆرسەتمەيدۇ.","u peqet buyruqqa boysunidu, hergiz qarshiliq körsetmeydu."]],"商务部":[["商务部负责贸易事务。","سودا مىنىستىرلىقى سودا ئىشلىرىغا مەسئۇل.","soda ministirliqi soda ishlirigha mes'ul."]],"啼笑皆非":[["这件事让人啼笑皆非。","بۇ ئىش كىشىنى كۈلدۈرۈپ يىغلىتىدۇ.","bu ish kishini küldürüp yighlitidu."]],"嘉奖":[["他因表现出色而获得嘉奖。","ئۇ ئالاھىدە نەتىجىسى ئۈچۈن مۇكاپاتلاندى.","u alahide netijisi üchün mukapatlandi."]],"嘎拉哈":[["嘎拉哈是传统玩具。","غالاخا ئەنئەنىۋى ئويۇنچۇق.","ghalaxa en'eniwi oyunchuq."]],"嗯哼":[["他嗯哼一声，表示同意。","ئۇ «ھەئە» دەپ باش لىڭشىتىپ، قوشۇلغانلىقىنى بىلدۈردى.","u «he'e» dep bash lingshitip, qoshulghanliqini bildürdi."]],"嘉士伯":[["嘉士伯啤酒深受人们喜爱。","كارلسىبېرگ پىۋىسى خەلق ئارىسىدا كۆپ ياقتۇرۇلىدۇ.","karlsibérg piwisi xelq arisida köp yaqturulidu."]],"喷薄":[["阳光喷薄而出。","قۇياش نۇرى ئېتىلىپ چىقتى.","quyash nuri étilip chiqti."]],"喷射":[["火箭的喷射力非常强大。","راكېتانىڭ ئاتقۇچ كۈچى ناھايىتى كۈچلۈك.","rakétaning atquch küchi nahayiti küchlük."]],"喷射机":[["喷射机在空中留下白色尾迹。","رېئاكتىپ ئايروپىلان ھاۋادا ئاق قۇيرۇق ئىز قالدۇرىدۇ.","réaktip ayropilan hawada aq quyruq iz qalduridu."]],"嘟嘟响":[["手机嘟嘟响了两声，提示有新消息。","تېلېفون دۇدۇڭ ئىككى قېتىم ياڭرىدى، يېڭى ئۇچۇر بارلىقىنى ئەسكەرتتى.","téléfon dudung ikki qétim yangridi, yéngi uchur barliqini eskertti."]],"嘶鸣":[["马儿发出嘶鸣声。","ئات كىشنەپ ئاۋاز چىقاردى.","at kishnep awaz chiqardi."]],"嘻哈":[["他喜欢嘻哈音乐。","ئۇ خىپ-خوپ مۇزىكىسىنى ياخشى كۆرىدۇ.","u xip-xop muzikisini yaxshi köridu."]],"严丝合缝":[["这件衣服做得严丝合缝，毫无瑕疵。","بۇ كىيىم ئىنتايىن ماسلاشتۇرۇلۇپ تىكىلگەن، ھېچقانداق نۇقسان يوق.","bu kiyim intayin maslashturulup tikilgen, héchqandaq nuqsan yoq."]],"单细胞":[["单细胞结构简单。","بىر ھۈجەيرىلىك قۇرۇلما ئاددىي.","bir hüjeyrilik qurulma addiy."]],"喹诺酮":[["喹诺酮类抗生素常用于治疗感染。","كىنولون تۈرىدىكى ئانتىبىئوتىكلار كۆپىنچە يۇقۇملارنى داۋالاشتا ئىشلىتىلىدۇ.","kinolon türidiki antibiotiklar köpinche yuqumlarni dawalashta ishlitilidu."]],"喻世明言":[["《喻世明言》是古代白话小说集。","«يۈشىمىڭيەن» قەدىمكى ئاق سۆزلەك رومانلار توپلىمى.","«yüshimingyen» qedimki aq sözlek romanlar toplimi."]],"四角裤":[["四角裤是男性常见的内裤款式。","تۆت بۇلۇڭلۇق ئىشتان ئەرلەر ئارىسىدا كۆپ ئۇچرايدىغان ئىچ كىيىم تۈرىدۇر.","töt bulungluq ishtan erler arisida köp uchraydighan ich kiyim türidur."]],"四轮马车":[["古代的四轮马车主要用于运输。","قەدىمكى تۆت چاقلىق ھارۋا ئاساسلىقى توشۇشتا ئىشلىتىلگەن.","qedimki töt chaqliq harwa asasliqi toshushta ishlitilgen."]],"回忆录":[["这本回忆录记录了他的一生。","بۇ خاتىرە ئۇنىڭ پۈتۈن ھاياتىنى خاتىرىلىگەن.","bu xatire uning pütün hayatini xatiriligen."]],"囤积居奇":[["商家囤积居奇，抬高物价。","سودىگەرلەر مال توپلاپ باھانى ئۆرلىتىۋاتىدۇ.","sodigerler mal toplap bahani örlitiwatidu."]],"国家新闻出版广电总局":[["国家新闻出版广电总局管理媒体事务。","دۆلەت ئاخبارات-نەشرىيات رادىيو-تېلېۋىزىيە ئومۇمىي ئىدارىسى مېدىيا ئىشلىرىنى باشقۇرىدۇ.","dölet axbarat-neshriyat radiyo-téléwiziye omumiy idarisi médiya ishlirini bashquridu."]],"园区":[["这个园区有很多现代化的设施。","بۇ باغچە رايونىدا نۇرغۇن زامانىۋى ئەسلىھەلەر بار.","bu baghche rayonida nurghun zamaniwi esliheler bar."]],"园艺":[["园艺能让生活更加丰富多彩。","باغۋەنچىلىك تۇرمۇشنى تېخىمۇ رەڭدار ۋە مول قىلالايدۇ.","baghwenchilik turmushni téximu rengdar we mol qilalaydu."]],"土葬":[["土葬是中国传统的安葬方式之一。","توپا كۆمۈش جۇڭگونىڭ ئەنئەنىۋى دەپنە قىلىش ئۇسۇللىرىنىڭ بىرى.","topa kömüsh junggoning en'eniwi depne qilish usullirining biri."]],"地保":[["地保负责调解纠纷。","يەر مۇھاپىزەتچىسى تالاش-تارتىشلارنى ياراشتۇرۇشقا مەسئۇل.","yer muhapizetchisi talash-tartishlarni yarashturushqa mes'ul."]],"坐好":[["请坐好，不要乱动。","ئولتۇرۇڭ، قالايمىقان قىمىڭ.","olturung, qalaymiqan qiming."]],"坎特伯雷故事集":[["《坎特伯雷故事集》是乔叟的作品。","«كانتېربېرى ھېكايىلىرى» چاۋسېرنىڭ ئەسىرى.","«kantérbéri hékayiliri» chawsérning esiri."]],"执委会":[["执委会负责日常管理。","ئىجرائىيە كومىتېتى كۈندىلىك باشقۇرۇشقا مەسئۇل.","ijraiye komitéti kündilik bashqurushqa mes'ul."]],"基因改造":[["基因改造可以创造新的生物品种。","Gېن ئۆزگەرتىش يېڭى بىئولوگىيەلىك تۈرلەرنى يارىتىشى مۇمكىن.","Gén özgertish yéngi biologiyelik türlerni yaritishi mumkin."]],"基因体":[["基因体是遗传物质的基本单位。","Gېن تەنچىسى ئىرسىي ماددىنىڭ ئاساسىي بىرلىكىدۇر.","Gén tenchisi irsiy maddining asasiy birlikidur."]],"基本功":[["他每天练习基本功，进步很快。","ئۇ ھەر كۈنى ئاساسىي مەشىق قىلىدۇ، تېز ئىلگىرىلەيدۇ.","u her küni asasiy meshiq qilidu, téz ilgirileydu."]],"基因库":[["基因库保存了物种的全部遗传信息。","گېن ئامبىرى تۈرلەرنىڭ بارلىق ئىرسىيەت ئۇچۇرىنى ساقلايدۇ.","gén ambiri türlerning barliq irsiyet uchurini saqlaydu."]],"块煤":[["一块块煤堆在角落。","بىر-بىر كۆمۈر پارچىلىرى بۇلۇڭدا دۆۋىلەنگەن.","bir-bir kömür parchiliri bulungda döwilengen."]],"墨竹工卡":[["墨竹工卡是西藏的一个著名景点。","موژۇگۇڭقا تىبەتنىڭ داڭلىق مەنزىرىلىك جايىدۇر.","mozhugungqa tibetning dangliq menzirilik jayidur."]],"壁虎":[["壁虎喜欢在墙壁上攀爬。","تام كەلتىكىسى تام ئۈستىدە يامىشىشنى ياخشى كۆرىدۇ.","tam keltikisi tam üstide yamishishni yaxshi köridu."]],"多孔性":[["多孔性影响材料强度。","كۆپ تۆشۈكلۈكلۈك ماتېرىيالنىڭ مۇستەھكەملىكىگە تەسىر كۆرسىتىدۇ.","köp töshüklüklük matériyalning mustehkemlikige tesir körsitidu."]],"大吹大擂":[["他大吹大擂自己的成就。","ئۇ ئۆز نەتىجىلىرىنى چوڭقۇر كۆپتۈرۈپ ماختاندى.","u öz netijilirini chongqur köptürüp maxtandi."]],"够本":[["这次投资总算够本了。","بۇ قېتىملىق مەبلەغ سېلىش ئاخىرى كاپالەتكە يەتتى.","bu qétimliq meblegh sélish axiri kapaletke yetti."]],"梦呓":[["他睡梦中说着梦呓。","ئۇ ئۇيقۇدا چۈشىدە سۆزلەپ ياتىدۇ.","u uyquda chüshide sözlep yatidu."]],"大巴":[["我们乘坐大巴旅行。","بىز چوڭ ئاپتوبۇستا سەپەر قىلدۇق.","biz chong aptobusta seper qilduq."]],"夜幕低垂":[["夜幕低垂，星星开始闪烁。","كېچە پەردىسى چۈشۈپ، يۇلتۇزلار چاقناپ باشلىدى.","kéche perdisi chüshüp, yultuzlar chaqnap bashlidi."]],"大水":[["水库的大水漫溢，淹没了周围的田地。","سۇ ئامبىرىنىڭ چوڭ سۈيى تېشىپ، ئەتراپتىكى ئېتىزلىقلارنى باسىۋەتتى.","su ambirining chong süyi téship, etraptiki étizliqlarni basiwetti."]],"大有可为":[["这个领域大有可为，值得探索。","بۇ ساھەدە چوڭ ئىشلارنى قىلىشقا بولىدۇ، ئىزدىنىشكە ئەرزىيدۇ.","bu sahede chong ishlarni qilishqa bolidu, izdinishke erziydu."]],"大键琴":[["大键琴是古老的乐器。","چوڭ كلاۋىسىن قەدىمىي چالغۇ.","chong klawisin qedimiy chalghu."]],"大余县":[["大余县历史悠久。","دایۈ ناھىيىسىنىڭ تارىخى ئۇزۇن.","dayü nahiyisining tarixi uzun."]],"天时":[["把握天时才能成功。","تەبىئىي پۇرسەتنى تۇتۇۋالغاندىلا ئاندىن مۇۋەپپەقىيەت قازىنىشقا بولىدۇ.","tebiiy pursetni tutuwalghandila andin muweppeqiyet qazinishqa bolidu."]],"天杀的":[["天杀的坏人终于受到了惩罚。","خۇدا ئۇرغان يامان ئادەم ئاخىرى جازاغا تارتىلدى.","xuda urghan yaman adem axiri jazagha tartildi."]],"天龙八部":[["《天龙八部》是一部经典武侠小说。","«ئاسمان ئەجدىھا سەككىز بۆلۈمى» كلاسسىك ۋۇشيا رومانىدۇر.","«asman ejdiha sekkiz bölümi» klassik wushya romanidur."]],"天龙国":[["天龙国是虚构的奇幻国度。","ئاسمان ئەجدىھا دۆلىتى ئويدۇرما فانتازىيە دۆلىتىدۇر.","asman ejdiha döliti oydurma fantaziye dölitidur."]],"天顶":[["天顶是教堂的顶部结构。","ئاسمان چوققىسى چېركاۋنىڭ ئۈستى قۇرۇلمىسىدۇر.","asman choqqisi chérkawning üsti qurulmisidur."]],"太原市":[["太原市位于山西省中部。","تەييۈەن شەھىرى شەنشى ئۆلكىسىنىڭ ئوتتۇرا قىسمىدا جايلاشقان.","teyyüen shehiri shenshi ölkisining ottura qismida jaylashqan."]],"天父":[["天父是宗教中的神。","تيەنفۇ دىنلاردىكى خۇدا.","tyenfu dinlardiki xuda."]],"天冬酰胺":[["天冬酰胺在蛋白质合成中起关键作用。","ئاسپاراگىن ئامىدى پروتىئىن سىنتېزىدا ھالقىلىق رول ئوينايدۇ.","asparagin amidi protiin sintézida halqiliq rol oynaydu."]],"奉化":[["奉化是浙江的一座城市。","فېڭخۇا جېجياڭدىكى بىر شەھەردۇر.","féngxua jéjyangdiki bir sheherdur."]],"奔流":[["河水奔流不息。","دەريا سۈيى ئۈزلۈكسىز ئېقىپ تۇرىدۇ.","derya süyi üzlüksiz éqip turidu."]],"天门冬":[["天门冬是一种常见的中药材。","تەڭرى دەرۋازىسى قىشى جۇڭيى دورىسىدا كۆپ ئۇچرايدىغان بىر خىل دورا ماتېرىيالى.","tengri derwazisi qishi jungyi dorisida köp uchraydighan bir xil dora matériyali."]],"套裤":[["他穿了一条深色套裤。","ئۇ توق رەڭلىك يەكتەك ئىشتان كىيىۋالغان.","u toq renglik yektek ishtan kiyiwalghan."]],"女儿墙":[["女儿墙保护着庭院的安全。","ئاياللار تېمى ھويلىنىڭ بىخەتەرلىكىنى قوغدايدۇ.","ayallar témi hoylining bixeterlikini qoghdaydu."]],"奥丁谐振器":[["这个设备叫奥丁谐振器。","بۇ ئۈسكۈنە ئودىن رېزوناتورى دەپ ئاتىلىدۇ.","bu üsküne odin rézonatori dep atilidu."]],"奥克苏斯河":[["奥克苏斯河发源于土耳其。","ئوكسۇس دەرياسى تۈركىيەدىن باشلىنىدۇ.","oksus deryasi türkiyedin bashlinidu."]],"妃子":[["这位妃子深受皇帝宠爱，备受恩宠。","بۇ جارىيە ئىمپېراتورنىڭ چوڭقۇر مۇھەببىتىگە ئېرىشىپ، ئالاھىدە ئىلتىپاتقا تولدى.","bu jariye impératorning chongqur muhebbitige ériship, alahide iltipatqa toldi."]],"妊娠试验":[["医生让我做了妊娠试验。","دوختۇر ماڭا ھامىلىدارلىق تەكشۈرۈشى ئېلىپ باردۇردى.","doxtur manga hamilidarliq tekshürüshi élip bardurdi."]],"如虎添翼":[["他如虎添翼，更加强大。","ئۇ يولۋاسقا قانات قوشۇلغاندەك، تېخىمۇ كۈچلۈك بولدى.","u yolwasqa qanat qoshulghandek, téximu küchlük boldi."]],"娱乐界":[["他在娱乐界很有名。","ئۇ كۆڭۈل ئېچىش ساھەسىدە بەك داڭلىق.","u köngül échish saheside bek dangliq."]],"婆媳":[["婆媳关系需要和谐。","كېلىن بىلەن قەينانا ئارىسىدىكى مۇناسىۋەت ئىناق بولۇشى كېرەك.","kélin bilen qeynana arisidiki munasiwet inaq bolushi kérek."]],"孤孑":[["孤孑在人群中显得特别孤单。","يالغۇز كىشى ئادەملەر ئارىسىدا ئالاھىدە يالغۇز كۆرۈندى.","yalghuz kishi ademler arisida alahide yalghuz köründi."]],"孙悦":[["孙悦是中国著名的篮球运动员。","سۈن يۆ جۇڭگونىڭ داڭلىق باسكېتبول تەنھەرىكەتچىسى.","sün yö junggoning dangliq baskétbol tenheriketchisi."]],"守兵":[["守兵们日夜守护着城池。","مۇداپىئە ئەسكەرلىرى كېچە-كۈندۈز شەھەرنى قوغدايدۇ.","mudapie eskerliri kéche-kündüz sheherni qoghdaydu."]],"守灵":[["家人在灵堂前守灵，表达哀思。","ئائىلە ئەزالىرى جىنازا ئۆيىنىڭ ئالدىدا ماتەم تۇتۇپ، قايغۇسىنى بىلدۈردى.","aile ezaliri jinaza öyining aldida matem tutup, qayghusini bildürdi."]],"孩子气":[["他的行为有些孩子气。","ئۇنىڭ قىلمىشىدا بالىلارچە ئىپادىلەر بار.","uning qilmishida balilarche ipadiler bar."]],"安妮·海瑟薇":[["安妮·海瑟薇是一位著名女演员。","ئاننى خەيسۋېي داڭلىق ئايال ئارتىس.","anni xeyswéy dangliq ayal artis."]],"安化":[["安化是中国著名的茶叶产地。","ئەنخۇا جۇڭگونىڭ مەشھۇر چاي ئىشلەپچىقىرىدىغان جايى.","enxua junggoning meshhur chay ishlepchiqiridighan jayi."]],"安非他明":[["安非他明常用于治疗注意力缺陷多动障碍。","ئامفېتامىن كۆپىنچە دىققەت يېتىشمەسلىك ۋە ھەرىكەت ئاۋارىچىلىقى بۇزۇلۇشىنى داۋالاشتا ئىشلىتىلىدۇ.","amfétamin köpinche diqqet yétishmeslik we heriket awarichiliqi buzulushini dawalashta ishlitilidu."]],"宗室":[["宗室成员享有特殊待遇。","ئەۋلاد ئەزالىرى ئالاھىدە مۇئامىلىگە ئىگە.","ewlad ezaliri alahide muamilige ige."]],"定标":[["定标器用于校准设备。","كالىبرلاش ئۈسكۈنىسى ئۈسكۈنىنى تەڭشەشكە ئىشلىتىلىدۇ.","kalibrlash üskünisi üskünini tengsheshke ishlitilidu."]],"家臣":[["家臣忠心耿耿地辅佐主公。","ئۆي خادىملىرى خوجايىنغا سادىقلىق بىلەن ياردەم قىلىدۇ.","öy xadimliri xojayingha sadiqliq bilen yardem qilidu."]],"寝食难安":[["他因焦虑而寝食难安。","ئۇ ئەندىشە سەۋەبىدىن يېيىش-ئىچىش ۋە ئۇخلاشتىن خاتىرجەم بولالمىدى.","u endishe sewebidin yéyish-ichish we uxlashtin xatirjem bolalmidi."]],"实事":[["要关注实事。","پاكىتقا دىققەت قىلىش كېرەك.","pakitqa diqqet qilish kérek."]],"实例":[["这个实例很有启发。","بۇ مىسال ئىنتايىن ئىلھام بېرىدۇ.","bu misal intayin ilham béridu."]],"宿敌":[["宿敌之间的对决备受期待。","ئۆزئارا قەدىمىي دۈشمەنلەر ئارىسىدىكى بەسلىشىش ئىنتايىن كۈتۈلمەكتە.","öz'ara qedimiy düshmenler arisidiki beslishish intayin kütülmekte."]],"宁河县":[["宁河县以农业发达而著称。","نىڭخې ناھىيىسى يېزا ئىگىلىكىنىڭ تەرەققىي قىلغانلىقى بىلەن تونۇلغان.","ningxé nahiyisi yéza igilikining tereqqiy qilghanliqi bilen tonulghan."]],"宁阳县":[["宁阳县有悠久的历史文化。","نىڭياڭ ناھىيىسىنىڭ تارىخىي مەدەنىيىتى ئۇزۇن.","ningyang nahiyisining tarixiy medeniyiti uzun."]],"实体层":[["实体层的处理需要特别注意。","ئەمەلىي گەۋدە قەۋىتىنى بىر تەرەپ قىلىشتا ئالاھىدە دىققەت قىلىش كېرەك.","emeliy gewde qewitini bir terep qilishta alahide diqqet qilish kérek."]],"宁城":[["宁城的建筑风格独特。","نىڭچېڭنىڭ بىناكارلىق ئۇسلۇبى ئۆزگىچە.","ningchéngning binakarliq uslubi özgiche."]],"宁明":[["宁明是广西的一个县。","نىڭمىڭ گۇاڭشىدىكى بىر ناھىيە.","ningming guangshidiki bir nahiye."]],"审问":[["警方对嫌疑人进行了审问。","ساقچىلار گۇماندارنى سوراق قىلدى.","saqchilar gumandarni soraq qildi."]],"宝山乡":[["宝山乡以丰富的矿产资源闻名。","باۋشەن يېزىسى باي مىنېرال بايلىقلىرى بىلەن تونۇلغان.","bawshen yézisi bay minéral bayliqliri bilen tonulghan."]],"封城":[["城市因疫情进入全面封城状态。","شەھەر يۇقۇم سەۋەبىدىن پۈتۈنلەي شەھەرنى پېچەتلەش ھالىتىگە كىردى.","sheher yuqum sewebidin pütünley sheherni péchetlesh halitige kirdi."]],"射影":[["光线穿过物体时会产生射影。","نۇر جىسىمدىن ئۆتكەندە سايە تەسىرى پەيدا بولىدۇ.","nur jisimdin ötkende saye tesiri peyda bolidu."]],"对视":[["两人长时间对视，气氛变得紧张。","ئىككىيلەن ئۇزۇن ۋاقىت بىر-بىرىگە قاراپ تۇردى، كەيپىيات جىددىيلەشتى.","ikkiylen uzun waqit bir-birige qarap turdi, keypiyat jiddiyleshti."]],"小铲子":[["他用小铲子清理花园里的落叶。","ئۇ كىچىك كۈرەك بىلەن باغچىدىكى خازانلىقلارنى تازىلىدى.","u kichik kürek bilen baghchidiki xazanliqlarni tazilidi."]],"小菜":[["这道小菜味道鲜美又下饭。","بۇ كىچىك تائام تەملىك ھەم تاماققا يارىشىدۇ.","bu kichik taam temlik hem tamaqqa yarishidu."]],"小蜜":[["小蜜是蜜蜂的一种。","كىچىك ھەرە ئارىنىڭ بىر تۈرىدۇر.","kichik here arining bir türidur."]],"尼希米记":[["《尼希米记》是《圣经》的一部分。","«نىھەمىيا خاتىرىسى» ئىنجىلنىڭ بىر قىسمىدۇر.","«nihemiya xatirisi» injilning bir qismidur."]],"小鸟依人":[["她小鸟依人的样子让人心疼。","ئۇنىڭ كىچىك قۇشقا ئوخشاش ئېرىپ تۇرغان ھالىتى كىشىنى ئېچىندۇرىدۇ.","uning kichik qushqa oxshash érip turghan haliti kishini échinduridu."]],"小牝牛":[["小牝牛是年轻的女性牛。","كىچىك سىيىر ياش ئايال كالىسى.","kichik siyir yash ayal kalisi."]],"屏东":[["屏东的海滩是度假的热门地点。","پىڭدۇڭنىڭ دېڭىز بويى دەم ئېلىشنىڭ قىزىق نۇقتىسىدۇر.","pingdungning déngiz boyi dem élishning qiziq nuqtisidur."]],"局中人":[["局中人难以看清全局。","ئىچىدىكى ئادەم پۈتۈن ۋەزىيەتنى ئېنىق كۆرۈشى قىيىن.","ichidiki adem pütün weziyetni éniq körüshi qiyin."]],"山药蛋":[["山药蛋是山药的另一种叫法。","تاغ يامىسى كارتىشكىسى تاغ يامىسىنىڭ يەنە بىر خىل ئاتىلىشىدۇر.","tagh yamisi kartishkisi tagh yamisining yene bir xil atilishidur."]],"山达基":[["他信奉山达基教多年。","ئۇ كۆپ يىللاردىن بۇيان سايېنتولوگىيە دىنىغا ئېتىقاد قىلىدۇ.","u köp yillardin buyan sayéntologiye dinigha étiqad qilidu."]],"山难":[["山难发生时，救援队迅速出动。","تاغ ئاپىتى يۈز بەرگەندە، قۇتقۇزۇش ئەترىتى دەرھال ھەرىكەتكە ئاتلاندى.","tagh apiti yüz bergende, qutquzush etriti derhal heriketke atlandi."]],"岔流":[["河流的岔流形成了多个支流。","دەريانىڭ تارماق ئېقىمى كۆپلىگەن قوشۇمچە ئېقىملارنى شەكىللەندۈردى.","deryaning tarmaq éqimi köpligen qoshumche éqimlarni shekillendürdi."]],"岩溶":[["岩溶地貌形成了独特的喀斯特景观。","تاش ئېرىش رېلىفى ئۆزگىچە كارست مەنزىرىسىنى شەكىللەندۈردى.","tash érish rélifi özgiche karst menzirisini shekillendürdi."]],"岩滨鹬":[["岩滨鹬是一种栖息在岩石海岸的鸟类。","تاش قىرغاق چىشچىقى تاش قىرغاقتا ياشايدىغان بىر قۇش تۈرى.","tash qirghaq chishchiqi tash qirghaqta yashaydighan bir qush türi."]],"岛盖部":[["岛盖部是虚构的部落名称。","ئارال قاپقىقى بۆلۈمى خەيالىي قەبىلە نامى.","aral qapqiqi bölümi xeyaliy qebile nami."]],"崔明慧":[["崔明慧是一位知名的学者。","چۇي مىڭخۇي تونۇلغان بىر ئالىم.","chuy mingxuy tonulghan bir alim."]],"州立":[["州立大学通常由州政府管理。","جوۋلى داشۆسى ئادەتتە جوۋ ھۆكۈمىتى تەرىپىدىن باشقۇرۇلىدۇ.","jowli dashösi adette jow hökümiti teripidin bashqurulidu."]],"巴伐利亚":[["巴伐利亚以啤酒闻名。","باۋارىيە پىۋاسى بىلەن داڭلىق.","bawariye piwasi bilen dangliq."]],"巴伦西亚":[["巴伦西亚是西班牙的城市。","ۋالېنسىيە ئىسپانىيەنىڭ بىر شەھىرى.","walénsiye ispaniyening bir shehiri."]],"巨细胞病毒":[["巨细胞病毒可通过血液传播。","گىگانت ھۈجەيرە ۋىرۇسى قان ئارقىلىق تارقىلىدۇ.","gigant hüjeyre wirusi qan arqiliq tarqilidu."]],"布斐":[["布斐是一种传统的织物工艺。","بۇفېي ئەنئەنىۋى رەخت ھۈنەرۈنچىلىكى.","buféy en'eniwi rext hünerünchiliki."]],"布格麦":[["布格麦是一位著名的音乐家。","بۇگمەي ئاتاقلىق بىر مۇزىكانت.","bugmey ataqliq bir muzikant."]],"巴拿马城":[["巴拿马城是巴拿马的首都。","پاناما شەھىرى پانامانىڭ پايتەختى.","panama shehiri panamaning paytexti."]],"布鲁克":[["布鲁克是一位著名的音乐家。","برۇك داڭلىق بىر مۇزىكانتتۇر.","bruk dangliq bir muzikanttur."]],"底面":[["底面平整光滑，适合放置物品。","ئاستى يۈزى تۈز ۋە سىلىق، بۇيۇم قويۇشقا ماس كېلىدۇ.","asti yüzi tüz we siliq, buyum qoyushqa mas kélidu."]],"底止":[["水流在河岸的底止处形成了明显的漩涡。","سۇ ئېقىمى دەريا بويىنىڭ ئاخىرقى چېكىدە ئېنىق قۇيۇن ھاسىل قىلدى.","su éqimi derya boyining axirqi chékide éniq quyun hasil qildi."]],"弄乱":[["请别把房间弄乱。","ئۆينى قالايمىقان قىلماڭ.","öyni qalaymiqan qilmang."]],"建瓯市":[["建瓯市是著名的茶都。","جەنئۇ شەھىرى مەشھۇر چاي پايتەختى.","jen'u shehiri meshhur chay paytexti."]],"建筑群":[["建筑群布局合理，风格统一。","بىنالار توپىنىڭ جايلاشتۇرۇلۇشى مۇۋاپىق، ئۇسلۇبى بىردەك.","binalar topining jaylashturulushi muwapiq, uslubi birdek."]],"张籍":[["张籍是唐代著名的诗人。","جاڭ جى تاڭ سۇلالىسىنىڭ مەشھۇر شائىرى.","jang ji tang sulalisining meshhur shairi."]],"弧光灯":[["弧光灯发出强光。","قەۋس نۇرلۇق چىراغ كۈچلۈك نۇر چىقىرىدۇ.","qews nurluq chiragh küchlük nur chiqiridu."]],"彼拉多":[["彼拉多曾审判过耶稣。","پىلاتۇس ئەيسانى سوراق قىلغان.","pilatus eysani soraq qilghan."]],"后任":[["他的后任继续推行这项政策。","ئۇنىڭ كېيىنكى ۋەزىپىدارى بۇ سىياسەتنى داۋاملىق ئىلگىرى سۈردى.","uning kéyinki wezipidari bu siyasetni dawamliq ilgiri sürdi."]],"影印本":[["影印本与原版几乎相同。","سۈرەت كۆپەيتىلگەن نۇسخا ئەسلى نۇسخا بىلەن دېگۈدەك ئوخشاش.","süret köpeytilgen nusxa esli nusxa bilen dégüdek oxshash."]],"待用餐":[["桌上还有待用餐。","ئۈستەلدە يېيىشكە تەييار تاماق بار.","üstelde yéyishke teyyar tamaq bar."]],"徜徉":[["傍晚时分，他在花园里徜徉。","كەچقۇرۇن ئۇ باغچىدا ئارام ئالدى.","kechqurun u baghchida aram aldi."]],"后置词":[["介词有时可以作后置词使用。","ئالدى قوشۇمچە سۆز بەزىدە ئارقا قوشۇمچە سۆز سۈپىتىدە ئىشلىتىلىشى مۇمكىن.","aldi qoshumche söz bezide arqa qoshumche söz süpitide ishlitilishi mumkin."]],"从轻":[["法官对罪犯从轻处罚。","سوتچى جىنايەتچىگە يېنىك جازا بەردى.","sotchi jinayetchige yénik jaza berdi."]],"从医":[["他选择从医，救死扶伤。","ئۇ داۋالاش ساھەسىنى تاللاپ، يارىلانغۇچىلارنى قۇتقۇزىدۇ.","u dawalash sahesini tallap, yarilanghuchilarni qutquzidu."]],"复婚":[["他们决定复婚，重新开始生活。","ئۇلار قايتا توي قىلىپ، يېڭىدىن تۇرمۇش باشلاشقا قارار قىلدى.","ular qayta toy qilip, yéngidin turmush bashlashqa qarar qildi."]],"心肌梗死":[["心肌梗死可能导致生命危险。","يۈرەك مۇسكۇلى ئۆلۈشى ھاياتقا خەتەر ئېلىپ كېلىشى مۇمكىن.","yürek muskuli ölüshi hayatqa xeter élip kélishi mumkin."]],"心理分析":[["这项心理分析揭示了行为背后的深层原因。","بۇ پىسخىكىلىق تەھلىل ھەرىكەت ئارقىسىدىكى چوڭقۇر سەۋەبلەرنى ئاشكارىلىدى.","bu pisxikiliq tehlil heriket arqisidiki chongqur seweblerni ashkarilidi."]],"忍痛割爱":[["她忍痛割爱，放弃了梦想。","ئۇ ئازاب-ئوقۇبەت بىلەن يارىتىدىغانلىرىدىن ۋاز كېچىپ، چۈشىدىن ۋاز كەچتى.","u azab-oqubet bilen yaritidighanliridin waz kéchip, chüshidin waz kechti."]],"志愿兵":[["志愿兵是军队中自愿服役的士兵。","پىدائىي ئەسكەرلەر ئارمىيەدە ئۆز ئىختىيارلىقى بىلەن خىزمەت قىلىدىغان ئەسكەرلەر.","pidaiy eskerler armiyede öz ixtiyarliqi bilen xizmet qilidighan eskerler."]],"性伴":[["她寻找合适的性伴。","ئۇ مۇۋاپىق جىنسىي ھەمراھ ئىزدىمەكتە.","u muwapiq jinsiy hemrah izdimekte."]],"恬静":[["山间一片恬静，无人打扰。","تاغ ئارىسى جىمجىت، ھېچكىم بۇزمايدۇ.","tagh arisi jimjit, héchkim buzmaydu."]],"恭贺":[["恭贺你考试顺利通过！","ئىمتىھاندىن ئوڭۇشلۇق ئۆتكەنلىكىڭىزنى تەبرىكلەيمەن!","imtihandin ongushluq ötkenlikingizni tebrikleymen!"]],"急欲":[["他急欲离开这里，一刻也待不下去。","ئۇ بۇ يەردىن ئالدىراپ كەتمەكچى، بىر مىنۇتمۇ تۇرالمايدۇ.","u bu yerdin aldirap ketmekchi, bir minutmu turalmaydu."]],"恶口":[["恶口伤人，切勿轻易出口。","يامان سۆز كىشىنى يارىلاندۇرىدۇ، ئاسانلىقچە ئېيتىپ قويماڭ.","yaman söz kishini yarilanduridu, asanliqche éytip qoymang."]],"意见不合":[["他们因意见不合而争吵。","ئۇلار پىكىر ئىختىلاپى سەۋەبىدىن تالاشتى.","ular pikir ixtilapi sewebidin talashti."]],"惟独":[["惟独他一个人留在原地。","پەقەت ئۇ يالغۇز ئۆز جايىدا قالدى.","peqet u yalghuz öz jayida qaldi."]],"恢宏":[["这座宫殿的规模恢宏，令人震撼。","بۇ ساراينىڭ كۆلىمى ھەيۋەتلىك بولۇپ، كىشىنى ھەيران قالدۇرىدۇ.","bu sarayning kölimi heywetlik bolup, kishini heyran qalduridu."]],"慕道友":[["他们因共同的兴趣成为慕道友。","ئۇلار ئورتاق قىزىقىش سەۋەبىدىن مۇدائۇي بولۇپ قالدى.","ular ortaq qiziqish sewebidin mudauy bolup qaldi."]],"庆阳":[["庆阳是甘肃省的一个城市。","چىڭياڭ گەنسۇ ئۆلكىسىدىكى بىر شەھەردۇر.","chingyang gensu ölkisidiki bir sheherdur."]],"凭眺":[["站在山顶凭眺远方。","تاغ چوققىسىدا تۇرۇپ يىراققا نەزەر سالدى.","tagh choqqisida turup yiraqqa nezer saldi."]],"凭空":[["他凭空消失了。","ئۇ پۈتۈنلەي غايىب بولدى.","u pütünley ghayib boldi."]],"惯贼":[["惯贼总是专挑高档商店下手。","ئادەتلەنگەن ئوغرى ھەمىشە ئالاھىدە دەرىجىلىك دۇكانلارنى نىشان قىلىدۇ.","adetlengen oghri hemishe alahide derijilik dukanlarni nishan qilidu."]],"感召":[["领袖的感召力让众人追随他。","رەھبەرنىڭ تەسىر كۈچى كۆپچىلىكنى ئۇنىڭغا ئەگەشتۈردى.","rehberning tesir küchi köpchilikni uninggha egeshtürdi."]],"应允":[["他应允了朋友的请求。","ئۇ دوستىنىڭ تەلىپىنى قوبۇل قىلدى.","u dostining telipini qobul qildi."]],"懵懂":[["他对事情还懵懂不知。","ئۇ ئىشتىن تېخى بىخەۋەر ئىدى.","u ishtin téxi bixewer idi."]],"恋战":[["他陷入了恋战的误区。","ئۇ ئۇرۇش قىلىش خاتالىقىغا پاتتى.","u urush qilish xataliqigha patti."]],"成都":[["成都是四川的省会城市。","چېڭدۇ سىچۇەننىڭ مەركىزىي شەھىرى.","chéngdu sichuenning merkiziy shehiri."]],"手拉手":[["他们手拉手一起过马路。","ئۇلار قول تۇتۇشۇپ بىرلىكتە يولنى كېسىپ ئۆتتى.","ular qol tutushup birlikte yolni késip ötti."]],"打不过":[["他打不过这个对手，只能认输。","ئۇ بۇ رەقىبىنى يېڭەلمەيدۇ، پەقەت تەسلىم بولۇشقا مەجبۇر.","u bu reqibini yéngelmeydu, peqet teslim bolushqa mejbur."]],"批覆":[["批覆是上级对下级请示的答复。","پىفۇ ئۈستى دەرىجىلىك ئورگاننىڭ تۆۋەن دەرىجىلىك ئورگاننىڭ يوليورۇق سورىشىغا بەرگەن جاۋابىدۇر.","pifu üsti derijilik organning töwen derijilik organning yolyoruq sorishigha bergen jawabidur."]],"拉取":[["程序会自动拉取最新数据。","پروگرامما ئاپتوماتىك ھالدا ئەڭ يېڭى سانلىق مەلۇماتنى تارتىپ ئالىدۇ.","programma aptomatik halda eng yéngi sanliq melumatni tartip alidu."]],"抓挠":[["猫会抓挠家具。","مۈشۈك ئۆي جاھازىلىرىنى تىرنايدۇ.","müshük öy jahazilirini tirnaydu."]],"抗震救灾指挥部":[["抗震救灾指挥部迅速展开了救援行动。","يەر تەۋرەشكە قارشى تۇرۇش ۋە ئاپەتتىن قۇتقۇزۇش قوماندانلىق ئىشتابى تېزلىكتە قۇتقۇزۇش ھەرىكىتىنى باشلىدى.","yer tewreshke qarshi turush we apettin qutquzush qomandanliq ishtabi tézlikte qutquzush herikitini bashlidi."]],"抗利尿激素":[["抗利尿激素调节体内水分平衡。","سىيدىك ئاجرىتىشقا قارشى ھورمون بەدەندىكى سۇ مۇۋازىنىتىنى تەڭشەيدۇ.","siydik ajritishqa qarshi hormon bedendiki su muwazinitini tengsheydu."]],"拍案叫绝":[["观众拍案叫绝。","تاماشىبىنلار ھەيران قېلىپ چاۋاك چېلىشتى.","tamashibinlar heyran qélip chawak chélishti."]],"招怨":[["他的行为招怨了。","ئۇنىڭ قىلمىشى ئۆچمەنلىك قوزغىدى.","uning qilmishi öchmenlik qozghidi."]],"招投标":[["公司参与招投标。","شىركەت تەENDERغا قاتناشتى.","shirket teENDERgha qatnashti."]],"拜泉":[["当地有祭拜泉水的传统习俗。","يەرلىكتە بۇلاققا چوقۇنۇش ئەنئەنىسى بار.","yerlikte bulaqqa choqunush en'enisi bar."]],"拿铁咖啡":[["拿铁咖啡口感丝滑。","لاتتې قەھۋەسىنىڭ تەمى يۇمشاق.","latté qehwesining temi yumshaq."]],"指疔":[["手指感染后形成了指疔。","بارماق ئىنفېكسىيەدىن كېيىن بارماق چىقى پەيدا بولدى.","barmaq inféksiyedin kéyin barmaq chiqi peyda boldi."]],"捉取":[["科学家捉取样本进行分析。","ئالىملار ئەۋرىزنى تەھلىل قىلىش ئۈچۈن ئېلىپ تۇتتى.","alimlar ewrizni tehlil qilish üchün élip tutti."]],"捉襟见肘":[["生活捉襟见肘，难以维持。","تۇرمۇش بەك تار، داۋاملاشتۇرۇش قىيىن.","turmush bek tar, dawamlashturush qiyin."]],"排长":[["排长带领队伍完成任务。","ۋزۋود باشلىقى ئەترەتنى يېتەكلەپ ۋەزىپىنى ئورۇندىدى.","wzwod bashliqi etretni yéteklep wezipini orundidi."]],"排水量":[["船的排水量很大。","كېمىنىڭ سۇ چىقىرىش مىقدارى بەك چوڭ.","kémining su chiqirish miqdari bek chong."]],"换言之":[["换言之，这就是关键所在。","باشقىچە ئېيتقاندا، بۇ ئاچقۇچلۇق نۇقتىدۇر.","bashqiche éytqanda, bu achquchluq nuqtidur."]],"揪斗":[["他们揪斗了反动分子。","ئۇلار رېئاكسىيەچى ئۇنسۇرلارنى تۇتۇپ كۆرەش قىلدى.","ular réaksiyechi unsurlarni tutup köresh qildi."]],"挥发油":[["植物含有挥发油。","ئۆسۈملۈكلەر ئۇچقۇچى ماي تەركىبىدە بولىدۇ.","ösümlükler uchquchi may terkibide bolidu."]],"搬出去":[["把东西搬出去。","نەرسىلەرنى سىرتقا يۆتكەڭ.","nersilerni sirtqa yötkeng."]],"挚切":[["他对朋友始终怀有挚切之情。","ئۇ دوستلىرىغا قەلبىدىن سەمىمىي مۇھەببەت باغلايدۇ.","u dostlirigha qelbidin semimiy muhebbet baghlaydu."]],"挚友良朋":[["他与挚友良朋常聚一堂。","ئۇ سادىق دوستلىرى بىلەن دائىم بىر يەرگە جەم بولىدۇ.","u sadiq dostliri bilen daim bir yerge jem bolidu."]],"摸爬滚打":[["他经过多年摸爬滚打才成功。","ئۇ كۆپ يىللاردىن بۇيان ئېزىلىپ-تارتىلىپ ئاندىن مۇۋەپپەقىيەت قازاندى.","u köp yillardin buyan ézilip-tartilip andin muweppeqiyet qazandi."]],"撒腿":[["她撒腿就跑，跑得飞快。","ئۇ دەرھال يۈگۈرۈپ كەتتى، ناھايىتى تېز يۈگۈردى.","u derhal yügürüp ketti, nahayiti téz yügürdi."]],"撑伞":[["他撑伞避雨。","ئۇ كۈنلۈك تۇتۇپ يامغۇردىن پاناھلىنىدۇ.","u künlük tutup yamghurdin panahlinidu."]],"折椅":[["这把折椅方便携带和存放。","بۇ قاتلىما ئورۇندۇق ئېلىپ يۈرۈش ۋە ساقلاشقا قولايلىق.","bu qatlima orunduq élip yürüsh we saqlashqa qolayliq."]],"撒尿":[["他跑进厕所撒尿。","ئۇكا ھاجەتخانىغا يۈگۈرۈپ كىردى.","uka hajetxanigha yügürüp kirdi."]],"撒手不管":[["他对孩子的事撒手不管。","ئۇ بالىسىنىڭ ئىشىغا قارىمايدۇ.","u balisining ishigha qarimaydu."]],"政和":[["政和地区以和谐稳定著称。","جېڭخې رايونى ئىناقلىق ۋە مۇقىملىق بىلەن تونۇلغان.","jéngxé rayoni inaqliq we muqimliq bilen tonulghan."]],"政敌":[["政敌之间的斗争异常激烈。","سىياسىي رەقىبلەر ئوتتۇرىسىدىكى كۈرەش ئىنتايىن شىددەتلىك.","siyasiy reqibler otturisidiki küresh intayin shiddetlik."]],"故宫博物院":[["故宫博物院收藏着大量珍贵文物。","گۇگۇڭ مۇزېيىدا كۆپ مىقداردا قىممەتلىك مەدەنىي يادىكارلىقلار ساقلىنىدۇ.","gugung muzéyida köp miqdarda qimmetlik medeniy yadikarliqlar saqlinidu."]],"敬老院":[["老人住在敬老院。","ياشانغانلار ياشانغانلار ئۆيىدە تۇرىدۇ.","yashanghanlar yashanghanlar öyide turidu."]],"敌方":[["敌方部队正在逼近。","دۈشمەن قىسىملىرى يېقىنلىشىۋاتىدۇ.","düshmen qisimliri yéqinlishiwatidu."]],"敌特":[["敌特分子被成功逮捕。","دۈشمەن ئالاھىدە ئەزالىرى مۇۋەپپەقىيەتلىك قولغا ئېلىندى.","düshmen alahide ezaliri muweppeqiyetlik qolgha élindi."]],"敞篷车":[["周末我们打算开敞篷车去郊游。","ھەپتە ئاخىرى بىز ئوچۇق ماشىنىدا سەھراغا سەيلەنگە چىقىشنى پىلانلىدۇق.","hepte axiri biz ochuq mashinida sehragha seylenge chiqishni pilanliduq."]],"文气":[["这篇文章充满文气与智慧。","بۇ ماقالە ئەدەبىي روھ ۋە پاراسەتكە تولغان.","bu maqale edebiy roh we parasetke tolghan."]],"斗室":[["斗室虽小，却充满书香。","دودۇڭ كىچىك بولسىمۇ، كىتاب ئىسپىرىغا تولغان.","dodung kichik bolsimu, kitab ispirigha tolghan."]],"斯大林主义":[["斯大林主义对20世纪政治影响深远。","ستالىنچىلىق 20-ئەسىر سىياسىتىگە چوڭقۇر تەسىر كۆرسەتتى.","stalinchiliq 20-esir siyasitige chongqur tesir körsetti."]],"斧头":[["这把斧头锋利得能砍断金属。","بۇ پالتا مېتالنى كېسەلەيدىغان دەرىجىدە ئۆتكۈر.","bu palta métalni késeleydighan derijide ötkür."]],"新南威尔士州":[["新南威尔士州是澳大利亚经济最发达的州之一。","يېڭى جەنۇبىي ۋېيلس شىتاتى ئاۋسترالىيەنىڭ ئىقتىسادى ئەڭ تەرەققىي قىلغان شىتاتلىرىنىڭ بىرى.","yéngi jenubiy wéyls shitati awstraliyening iqtisadi eng tereqqiy qilghan shitatlirining biri."]],"新营市":[["新营市是一座历史悠久的城市。","شىنيىڭ شەھىرى ئۇزۇن تارىخقا ئىگە شەھەر.","shinying shehiri uzun tarixqa ige sheher."]],"新埤乡":[["新埤乡以茶叶著称。","شىنپى يېزىسى چاي بىلەن داڭلىق.","shinpi yézisi chay bilen dangliq."]],"新产品推介会":[["新产品推介会吸引了许多客户。","يېڭى مەھسۇلات تونۇشتۇرۇش يىغىنى كۆپلىگەن خېرىدارلارنى جەلپ قىلدى.","yéngi mehsulat tonushturush yighini köpligen xéridarlarni jelp qildi."]],"新闻周刊":[["《新闻周刊》每周都会发布深度报道。","«خەۋەر ھەپتىلىكى» ھەر ھەپتە چوڭقۇر ئاخباراتلارنى ئېلان قىلىدۇ.","«xewer heptiliki» her hepte chongqur axbaratlarni élan qilidu."]],"早茶":[["广东人习惯喝早茶聊天。","گۇاڭدۇڭلۇقلار ئەتىگەنلىك چاي ئىچىپ پاراڭلىشىشقا ئادەتلەنگەن.","guangdungluqlar etigenlik chay ichip paranglishishqa adetlengen."]],"旱灾":[["旱灾导致农作物大面积减产。","قۇرغاقچىلىق ئاپىتى يېزا ئىگىلىك زىرائەتلىرىنىڭ زور كۆلەمدە ئازىيىشىغا سەۋەب بولدى.","qurghaqchiliq apiti yéza igilik ziraetlirining zor kölemde aziyishigha seweb boldi."]],"明喻":[["明喻是一种直接的比喻手法。","ئوچۇق ئوخشىتىش بىۋاسىتە ئوخشىتىش ئۇسۇلىدۇر.","ochuq oxshitish biwasite oxshitish usulidur."]],"易建联":[["易建联是著名篮球运动员。","ئى جيەنلىيەن داڭلىق باسكېتبول تەنھەرىكەتچىسىدۇر.","i jyenliyen dangliq baskétbol tenheriketchisidur."]],"明治":[["明治时代是日本近代化的开端。","مېيجى دەۋرى ياپونىيەنىڭ زامانىۋىلىشىشىنىڭ باشلىنىشى.","méyji dewri yaponiyening zamaniwilishishining bashlinishi."]],"昆阳":[["昆阳的古城墙保存完好。","قۈنياننىڭ قەدىمىي شەھەر تېمى تولۇق ساقلىنىپ قالغان.","qünyanning qedimiy sheher témi toluq saqlinip qalghan."]],"暗伤":[["这次事故给他留下了暗伤。","بۇ ۋەقە ئۇنىڭغا يوشۇرۇن زەخمە قалدۇردى.","bu weqe uninggha yoshurun zexme qалdurdi."]],"晴隆县":[["晴隆县以独特的自然风光著称。","جىڭلۇڭ ناھىيىسى ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن تونۇلغان.","jinglung nahiyisi özgiche tebiiy menzirisi bilen tonulghan."]],"书库":[["图书馆的书库很大。","كۇتۇپخانىنىڭ كىتاب ساقلىغۇچىسى ئىنتايىن چوڭ.","kutupxanining kitab saqlighuchisi intayin chong."]],"曲江":[["曲江是古代著名的文化区。","چۈجياڭ قەدىمىي داڭلىق مەدەنىيەت رايونىدۇر.","chüjyang qedimiy dangliq medeniyet rayonidur."]],"木卡姆":[["木卡姆是一种传统的音乐形式。","مۇقام ئەنئەنىۋى مۇزىكا شەكلى.","muqam en'eniwi muzika shekli."]],"木垒哈萨克自治县":[["木垒哈萨克自治县风景优美。","مورى قازاق ئاپتونوم ناھىيىسىنىڭ مەنزىرىسى گۈزەل.","mori qazaq aptonom nahiyisining menzirisi güzel."]],"有目共睹":[["他的进步有目共睹。","ئۇنىڭ تەرەققىياتى ھەممىگە ئاشكارا.","uning tereqqiyati hemmige ashkara."]],"有眼不识泰山":[["他真是有眼不识泰山。","ئۇ ھەقىقەتەن كۆزى چىللا، تاغنى تونۇمىدى.","u heqiqeten közi chilla, taghni tonumidi."]],"杜尚别":[["杜尚别是塔吉克斯坦首都。","دۇشەنبە تاجىكىستاننىڭ پايتەختىدۇر.","dushenbe tajikistanning paytextidur."]],"朱利娅":[["朱利娅是一位才华横溢的演员。","جۇلىيا تالانتلىق ئارتىس.","juliya talantliq artis."]],"本垒打":[["他打出了一记漂亮的本垒打。","ئۇ بىر چىرايلىق بېيزىقارا زەربىسىنى ئۇردى.","u bir chirayliq béyziqara zerbisini urdi."]],"东洋鬼":[["东洋鬼是旧时对日本人的贬称。","شەرقىي دېڭىز شەيتانى كونا زاماندا ياپونىيەلىكلەرگە قارىتىلغان كەمسىتىش ئاتالغۇسى.","sherqiy déngiz sheytani kona zamanda yaponiyeliklerge qaritilghan kemsitish atalghusi."]],"东安":[["东安是湖南省的一个地级市。","دۇڭئەن خۇنەن ئۆلكىسىدىكى بىر ۋىلايەت دەرىجىلىك شەھەردۇر.","dung'en xunen ölkisidiki bir wilayet derijilik sheherdur."]],"东安区":[["东安区是东安市的政治中心。","دۇڭئەن رايونى دۇڭئەن شەھىرىنىڭ سىياسىي مەركىزىدۇر.","dung'en rayoni dung'en shehirining siyasiy merkizidur."]],"东方航空":[["东方航空是中国主要的航空公司之一。","شەرقىي ئاۋىياتسىيە جۇڭگونىڭ ئاساسلىق ئاۋىياتسىيە شىركەتلىرىنىڭ بىرىدۇر.","sherqiy awiyatsiye junggoning asasliq awiyatsiye shirketlirining biridur."]],"东光":[["东光以传统工艺闻名全国。","دۇڭگۇاڭ ئەنئەنىۋى ھۈنەرۋەنچىلىكى بىلەن پۈتۈن مەملىكەتكە تونۇلغان.","dungguang en'eniwi hünerwenchiliki bilen pütün memliketke tonulghan."]],"东汉":[["东汉时期是中国历史上的重要阶段。","شەرقىي خەن سۇلالىسى دەۋرى جۇڭگو تارىخىدىكى مۇھىم بىر باسقۇچ.","sherqiy xen sulalisi dewri junggo tarixidiki muhim bir basquch."]],"杜月笙":[["杜月笙是民国时期的名人。","دۇيۇشېڭ جۇڭخۇا مىنگو دەۋرىدىكى مەشھۇر شەخس.","duyushéng jungxua mingo dewridiki meshhur shexs."]],"果肉":[["果肉细腻，口感极佳。","مېۋە گۆشى نەپىس، تەمى ئىنتايىن ياخشى.","méwe göshi nepis, temi intayin yaxshi."]],"东观汉记":[["《东观汉记》是重要的史学著作。","«دۇڭگۇەن خەن جى» مۇھىم تارىخشۇناسلىق ئەسىرى.","«dungguen xen ji» muhim tarixshunasliq esiri."]],"柴鸡":[["柴鸡蛋比普通鸡蛋更营养。","توخۇ تۇخۇمى ئادەتتىكى تۇخۇمدىن تېخىمۇ ئوزۇقلۇق.","toxu tuxumi adettiki tuxumdin téximu ozuqluq."]],"柴电机车":[["柴电机车是早期交通工具。","دىزېل ئېلېكتر ئوچاقلىق پويىز ئەرەلەردىكى قاتناش قورالى ئىدى.","dizél éléktr ochaqliq poyiz erelerdiki qatnash qorali idi."]],"柴胡":[["柴胡是一种常用的中药材。","چەيخۇ كۆپ ئىشلىتىلىدىغان بىر خىل جۇڭگو تېبابىتى دورىسىدۇر.","cheyxu köp ishlitilidighan bir xil junggo tébabiti dorisidur."]],"桃子":[["桃子是夏季常见的水果。","شاپتۇل يازدا كۆپ ئۇچرايدىغان مېۋە.","shaptul yazda köp uchraydighan méwe."]],"桃源":[["桃源是一个宁静的小村庄。","شاپتۇل بۇلاقى ئىنتايىن جىمجىت كىچىك كەنت.","shaptul bulaqi intayin jimjit kichik kent."]],"梅毒":[["梅毒是一种性传播疾病。","زەھەرلىك چېكىملىك جىنسىي يول بىلەن يۇقىدىغان كېسەللىك.","zeherlik chékimlik jinsiy yol bilen yuqidighan késellik."]],"梁河县":[["梁河县位于云南省的西南部。","Lianghe nahiyisi Yünnén ölkisining جەنۇبىي غەربىي قىسمىدا جايلاشقان.","Lianghe nahiyisi Yünnén ölkisining jenubiy gherbiy qismida jaylashqan."]],"梅塞德斯奔驰":[["梅塞德斯奔驰是世界知名的汽车品牌。","Mercedes-Benz bolsa دۇنياغا داڭلىق ئاپتوموبىل ماركىسى.","Mercedes-Benz bolsa dunyagha dangliq aptomobil markisi."]],"棋盘":[["棋盘上的每个格子都经过精心设计。","چەمبىرەك تاختىسىدىكى ھەر بىر كاتەكچە ئىنچىكە لايىھەلەنگەن.","chembirek taxtisidiki her bir katekche inchike layihelengen."]],"棕尾伯劳":[["棕尾伯劳的羽毛颜色鲜艳。","قوڭۇر قۇيرۇقلىق قارغۇچىنىڭ پەيلىرىنىڭ رەڭگى پارقىراق.","qongur quyruqliq qarghuchining peylirining renggi parqiraq."]],"棋高一着":[["他在关键时刻棋高一着，赢得了胜利。","ئۇ ھالقىلىق پەيتتە بىر پىيادە ئالدىنقىلىق قىلىپ، غەلىبە قازاندى.","u halqiliq peytte bir piyade aldinqiliq qilip, ghelibe qazandi."]],"棘鼻青岛龙":[["棘鼻青岛龙是古老的恐龙。","تىكەنلىك بۇرۇن چىڭداۋ ئەجدىھاسى قەدىمكى دىنوزاۋر.","tikenlik burun chingdaw ejdihasi qedimki dinozawr."]],"棕红":[["棕红是一种温暖而沉稳的颜色。","قوڭۇر قىزىل ئىللىق ھەم مۇقىم بىر رەڭدۇر.","qongur qizil illiq hem muqim bir rengdur."]],"棕背雪雀":[["棕背雪雀栖息在高海拔地区。","قوڭۇر دۈمبىلىك قارلىق چىمچىقى ئېگىز بىيىكلىكتىكى رايونلاردا ياشايدۇ.","qongur dümbilik qarliq chimchiqi égiz biyikliktiki rayonlarda yashaydu."]],"棕胸蓝姬鹟":[["棕胸蓝姬鹟的飞行速度很快。","قوڭۇر كۆكرەكلىك كۆك پەرۋاز قۇشىنىڭ ئۇچۇش سۈرئىتى ئىنتايىن تېز.","qongur kökreklik kök perwaz qushining uchush sür'iti intayin téz."]],"椰丝":[["椰丝可以撒在蛋糕上。","كوكونۇت تالاسى تورت ئۈستىگە چېچىلىدۇ.","kokonut talasi tort üstige chéchilidu."]],"榜葛剌":[["榜葛剌是古代的一个地名。","بەنگال قەدىمكى زاماندىكى بىر يەر نامىدۇر.","bengal qedimki zamandiki bir yer namidur."]],"桤树":[["山坡上长满了桤树。","تاغ باغرى تەل دەرىخى بىلەن تولغان.","tagh baghri tel derixi bilen tolghan."]],"槽坊":[["古代槽坊负责加工粮食作物。","قەدىمكى ئوقۇر ئۆيى ئاشلىق زىرائەتلىرىنى پىششىقلايتتى.","qedimki oqur öyi ashliq ziraetlirini pishshiqlaytti."]],"条目":[["目录中的每个条目都标注了页码。","مۇندەرىجىدىكى ھەر بىر ماددا بەت نومۇرى بىلەن بەلگىلەنگەن.","munderijidiki her bir madda bet nomuri bilen belgilengen."]],"乐昌之镜":[["乐昌之镜是当地著名的景点。","لېچاڭ ئەينىكى يەرلىكتىكى داڭلىق مەنزىرە نۇقتىسى.","léchang eyniki yerliktiki dangliq menzire nuqtisi."]],"榆阳":[["榆阳区是榆林市的核心区域。","يۈياڭ رايونى يۈلىن شەھىرىنىڭ يادرولۇق رايونىدۇر.","yüyang rayoni yülin shehirining yadroluq rayonidur."]],"机巧":[["他的机巧令人惊叹。","ئۇنىڭ ماھارىتى كىشىنى ھەيران قالدۇرىدۇ.","uning mahariti kishini heyran qalduridu."]],"横街":[["这条横街连接着两条主要道路。","بۇ كۆندىلەڭ كوچا ئىككى مۇھىم يولنى تۇتاشتۇرىدۇ.","bu köndileng kocha ikki muhim yolni tutashturidu."]],"档案盒":[["档案盒用于存放重要文档。","ارخىپ قۇتىسى مۇھىم ھۆججەتلەرنى ساقلاشقا ئىشلىتىلىدۇ.","arxip qutisi muhim höjjetlerni saqlashqa ishlitilidu."]],"树洞":[["树洞里藏着许多小昆虫。","دەرەخ كاۋىكىدا نۇرغۇن كىچىك ھاشاراتلار يوشۇرۇنغان.","derex kawikida nurghun kichik hasharatlar yoshurunghan."]],"欧巴":[["欧巴是韩语中对哥哥的称呼。","ئوپپا كورىيە تىلىدا ئاكا دېگەن مەنىدە.","oppa koriye tilida aka dégen menide."]],"欧洲共同体":[["欧洲共同体是欧盟的前身组织。","ياۋروپا ئورتاق گەۋدىسى ياۋروپا ئىتتىپاقىنىڭ ئالدىنقى تەشكىلاتى.","yawropa ortaq gewdisi yawropa ittipaqining aldinqi teshkilati."]],"正确处理":[["我们应该正确处理问题。","بىز مەسىلىنى توغرا بىر تەرەپ قىلىشىمىز كېرەك.","biz mesilini toghra bir terep qilishimiz kérek."]],"正镶白旗":[["正镶白旗风景优美。","جېڭشياڭبەي چىڭىنىڭ مەنزىرىسى ئىنتايىن گۈزەل.","jéngshyangbey chingining menzirisi intayin güzel."]],"欠揍":[["他说的话简直欠揍，太嚣张了。","ئۇنىڭ دېگەن گەپلىرى ھەقىقەتەن ئۇرۇشقا تېگىشلىك، بەك تەكەببۇرلۇق قىلدى.","uning dégen gepliri heqiqeten urushqa tégishlik, bek tekebburluq qildi."]],"武库":[["古代武库用于储存兵器。","قەدىمكى زاماندا ھەربىي ساقلاش ئامبىرى قورال-ياراغ ساقلاشقا ئىشلىتىلگەن.","qedimki zamanda herbiy saqlash ambiri qoral-yaragh saqlashqa ishlitilgen."]],"死无对证":[["他已离世，死无对证。","ئۇ ئاللىقاچان ئالەمدىن ئۆتتى، ئۆلگەنگە گۇۋاھ بولغىلى بولمايدۇ.","u alliqachan alemdin ötti, ölgenge guwah bolghili bolmaydu."]],"死守":[["他们誓要死守这座城池。","ئۇلار بۇ شەھەرنى ئۆلگىچە قوغداشقا قەسەم قىلدى.","ular bu sheherni ölgiche qoghdashqa qesem qildi."]],"正数":[["正数是指大于零的实数。","مۇسبەت سان نۆلدىن چوڭ ھەقىقىي ساننى كۆرسىتىدۇ.","musbet san nöldin chong heqiqiy sanni körsitidu."]],"归西":[["老人安详归西。","بوۋاي تىنچ ھالدا ئالەمدىن ئۆتتى.","boway tinch halda alemdin ötti."]],"母党":[["母党是政党的核心组织。","ئانا پارتىيە سىياسىي پارتىيەنىڭ يادرولۇق تەشكىلاتىدۇر.","ana partiye siyasiy partiyening yadroluq teshkilatidur."]],"每夜":[["每夜她都会为家人准备晚餐。","ھەر كېچە ئۇ ئائىلىسى ئۈچۈن كەچلىك تاماق تەييارلايدۇ.","her kéche u ailisi üchün kechlik tamaq teyyarlaydu."]],"每日邮报":[["每日邮报是英国著名的报纸。","كۈندىلىك پوچتا گېزىتى ئەنگلىيەنىڭ مەشھۇر گېزىتىدۇر.","kündilik pochta géziti engliyening meshhur gézitidur."]],"毛遂自荐":[["他毛遂自荐担任队长。","ئۇ خام سۈيى ئۆزىنى تەۋسىيە قىلىپ ئەترەت باشلىقى بولۇشقا تەلەپ قىلدى.","u xam süyi özini tewsiye qilip etret bashliqi bolushqa telep qildi."]],"毋忘":[["毋忘历史，方能前行。","تارىخنى ئۇنۇتماسلىق كېرەك، شۇنداق بولغاندىلا ئىلگىرىلىيەلەيمىز.","tarixni unutmasliq kérek, shundaq bolghandila ilgiriliyeleymiz."]],"残喘":[["他只剩下残喘，生命垂危。","ئۇنىڭ پەقەت يېرىم نەپىسى قالدى، ھاياتى خەتەردە ئىدى.","uning peqet yérim nepisi qaldi, hayati xeterde idi."]],"残存":[["只有少数人残存下来，幸免于难。","پەقەت ئاز ساندىكى كىشىلەرلا ئامان قالدى، ئاپەتتىن قۇتۇلدى.","peqet az sandiki kishilerla aman qaldi, apettin qutuldi."]],"气态":[["水在常温下呈气态，容易蒸发。","سۇ نورمال تېمپېراتۇرىدا گاز ھالىتىدە بولۇپ، ئاسان پارلىنىدۇ.","su normal témpératurida gaz halitide bolup, asan parlinidu."]],"毛主席":[["毛主席是伟大的领导人。","ماۋ رەئىس جۇڭگو كوممۇنىستىك پارتىيەسىنىڭ ئۇلۇغ رەھبىرىدۇر.","maw reis junggo kommunistik partiyesining ulugh rehbiridur."]],"氢氧化钾":[["氢氧化钾具有强碱性。","ھىدروگېن-ئوكسىدلانغان كالىي كۈچلۈك ئىشقارلىققا ئىگە.","hidrogén-oksidlanghan kaliy küchlük ishqarliqqa ige."]],"水管":[["水管漏水需要修理。","سۇ تۇرۇبىسىدىن سۇ ئېقىۋاتىدۇ، رېمونت قىلىش كېرەك.","su turubisidin su éqiwatidu, rémont qilish kérek."]],"民权县":[["民权县历史悠久，文化深厚。","مىنچۇەن ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى چوڭقۇر.","minchuen nahiyisining tarixi uzun, medeniyiti chongqur."]],"民营企业":[["这家民营企业近年来发展迅速。","بۇ خۇسۇسىي كارخانا يېقىنقى يىللاردا تېز تەرەققىي قىلدى.","bu xususiy karxana yéqinqi yillarda téz tereqqiy qildi."]],"水务":[["水务是指与水资源管理相关的事务。","سۇ ئىشلىرى سۇ بايلىقىنى باشقۇرۇش بىلەن مۇناسىۋەتلىك ئىشلارنى كۆرسىتىدۇ.","su ishliri su bayliqini bashqurush bilen munasiwetlik ishlarni körsitidu."]],"永春":[["永春的茶文化历史悠久。","يۇڭچۈننىڭ چاي مەدەنىيىتى ئۇزۇن تارىخقا ئىگە.","yungchünning chay medeniyiti uzun tarixqa ige."]],"求是":[["实事求是是科学的态度。","ئەمەلىيەتتىن ھەقىقەت ئىزدەش ئىلمىي پوزىتسىيەدۇر.","emeliyettin heqiqet izdesh ilmiy pozitsiyedur."]],"污水处理厂":[["污水处理厂能净化污水。","پاكىز سۇ زاۋۇتى پاكىز سۇنى تازىلىيالايدۇ.","pakiz su zawuti pakiz suni taziliyalaydu."]],"气馁":[["失败让他一度感到气馁。","مەغلۇبىيەت ئۇنى بىر مەزگىل روھىي چۈشكۈنلۈككە سالدى.","meghlubiyet uni bir mezgil rohiy chüshkünlükke saldi."]],"汾阳市":[["汾阳市是汾河沿岸的重要城市。","فېنياڭ شەھىرى فېنخې دەرياسى بويىدىكى مۇھىم شەھەر.","fényang shehiri fénxé deryasi boyidiki muhim sheher."]],"沙洋县":[["沙洋县以农业闻名。","شايەن ناھىيىسى يېزا ئىگىلىكى بىلەن داڭلىق.","shayen nahiyisi yéza igiliki bilen dangliq."]],"泉州市":[["泉州市以海洋文化闻名。","چۈەنجۇ شەھىرى دېڭىز مەدەنىيىتى بىلەن داڭلىق.","chüenju shehiri déngiz medeniyiti bilen dangliq."]],"法轮常转":[["法轮常转，寓意佛法永流传。","فالۇن دائىم ئايلىنىپ تۇرىدۇ، بۇ بۇددا قانۇنىنىڭ مەڭگۈ داۋاملىشىشىنى بىلدۈرىدۇ.","falun daim aylinip turidu, bu budda qanunining menggü dawamlishishini bildüridu."]],"沙瓦":[["沙瓦是古老的祭祀仪式。","ساۋا قەدىمىي قۇربانلىق مۇراسىمىدۇر.","sawa qedimiy qurbanliq murasimidur."]],"沙西米":[["沙西米是一种生鱼片料理。","ساشىمى بىر خىل خام بېلىق تائامىدۇر.","sashimi bir xil xam béliq taamidur."]],"法属圭亚那":[["法属圭亚那是法国的海外省。","فىرانسىيەگە تەۋە گۋىيانا فىرانسىيەنىڭ چەتئەلدىكى ئۆلكىسىدۇر.","firansiyege tewe gwiyana firansiyening chet'eldiki ölkisidur."]],"洗冤":[["他努力洗冤，证明清白。","ئۇ ئۆزىنىڭ گۇناھسىزلىقىنى ئىسپاتلاش ئۈچۈن تىرىشتى.","u özining gunahsizliqini ispatlash üchün tirishti."]],"津液":[["津液是中医理论中的基本概念。","جىنيې جۇڭگو تېبابىتى نەزەرىيەسىدىكى ئاساسىي ئۇقۇم.","jinyé junggo tébabiti nezeriyesidiki asasiy uqum."]],"洧水":[["洧水是一条历史悠久的河流。","ۋېيشۇي ئۇزۇن تارىخقا ئىگە بىر دەريا.","wéyshuy uzun tarixqa ige bir derya."]],"洗涤":[["洗衣机可以自动洗涤衣物。","كىيىم يۇيۇش ماشىنىسى كىيىملەرنى ئاپتوماتىك يۇيالايدۇ.","kiyim yuyush mashinisi kiyimlerni aptomatik yuyalaydu."]],"洗涤机":[["这台洗涤机效率很高。","بۇ يۇيۇش ماشىنىسىنىڭ ئۈنۈمى بەك يۇقىرى.","bu yuyush mashinisining ünümi bek yuqiri."]],"海德尔堡":[["海德尔堡是德国的一个城市。","خەيدېلبېرگ گېرمانىيەنىڭ بىر شەھىرى.","xeydélbérg gérmaniyening bir shehiri."]],"海东青":[["海东青是一种体型巨大的猛禽。","بۈركۈت بىر خىل گەۋدىسى زور يىرتقۇچ قۇش.","bürküt bir xil gewdisi zor yirtquch qush."]],"泾源县":[["泾源县地处六盘山地区。","جىڭيۈەن ناھىيىسى ليۇپەن تاغ رايونىدا جايلاشقان.","jingyüen nahiyisi lyupen tagh rayonida jaylashqan."]],"涮羊肉":[["涮羊肉火锅。","قوي گۆشى قازانلىقى.","qoy göshi qazanliqi."]],"涉世":[["他涉世尚浅，经验不足。","ئۇ دۇنياغا يېڭى كەلگەن، تەجرىبىسى يېتەرلىك ئەمەس.","u dunyagha yéngi kelgen, tejribisi yéterlik emes."]],"浮泛":[["他的观点过于浮泛，缺乏深度。","ئۇنىڭ كۆز قارىشى بەك يۈزەكى، چوڭقۇرلۇقى يېتەرلىك ئەمەس.","uning köz qarishi bek yüzeki, chongqurluqi yéterlik emes."]],"深孚众望":[["他深孚众望，成为领袖。","ئۇ خەلقنىڭ چوڭقۇر ئىشەنچىسىگە ئېرىشىپ، رەھبەر بولدى.","u xelqning chongqur ishenchisige ériship, rehber boldi."]],"浩然":[["浩然正气充满天地之间。","ھەقىقىي ئادالەت روھى ئاسمان-زېمىن ئارىسىغا تولغان.","heqiqiy adalet rohi asman-zémin arisigha tolghan."]],"清炒":[["清炒时蔬保留了蔬菜的原味。","چىڭقورۇلان كۆكتات كۆكتاتنىڭ ئەسلى تەمىنى ساقلاپ قالغان.","chingqorulan köktat köktatning esli temini saqlap qalghan."]],"渡轮":[["渡轮定期往返于两地。","پاروم ئىككى جاي ئارىسىدا مۇنتىزىم قاتنايدۇ.","parom ikki jay arisida muntizim qatnaydu."]],"涡轮":[["涡轮是发动机的关键部件。","تۈرۈبىنا ماتورنىڭ ئاچقۇچلۇق زاپچاسىدۇر.","türübina matorning achquchluq zapchasidur."]],"浸入":[["布料浸入染液中变色。","رەخت بوياق سۇيۇقلۇقىغا چىلاپ چىلانسا رەڭگى ئۆزگىرىدۇ.","rext boyaq suyuqluqigha chilap chilansa renggi özgiridu."]],"湄洲岛":[["湄洲岛是著名的旅游胜地。","مېيجۇ ئارىلى مەشھۇر ساياھەت مەنزىلى.","méyju arili meshhur sayahet menzili."]],"准绳":[["诚信是为人处事的准绳。","سەمىمىيەت كىشىلىك مۇئامىلىنىڭ ئۆلچىمىدۇر.","semimiyet kishilik muamilining ölchimidur."]],"游客止步":[["游客止步，请勿进入。","ساياھەتچىلەر توختىسۇن، كىرمەڭلار.","sayahetchiler toxtisun, kirmenglar."]],"溪州乡":[["溪州乡历史悠久。","شىجۇ يېزىسىنىڭ تارىخى ئۇزۇن.","shiju yézisining tarixi uzun."]],"涤虑":[["冥想有助于涤虑静心。","مېدىتاتسىيە پىكىرنى تازىلاپ كۆڭۈلنى تىنچلاشتۇرۇشقا ياردەم قىلىدۇ.","méditatsiye pikirni tazilap köngülni tinchlashturushqa yardem qilidu."]],"潜水者":[["潜水者必须熟悉水下环境。","سۇ ئاستىغا چۆمۈگۈچى سۇ ئاستى مۇھىتىنى چوقۇم ياخشى بىلىشى كېرەك.","su astigha chömügüchi su asti muhitini choqum yaxshi bilishi kérek."]],"满足感":[["完成目标后，他感受到了强烈的满足感。","نىشانىنى ئورۇندىغاندىن كېيىن، ئۇ كۈچلۈك قانائەت ھېسسىياتىنى ھېس قىلدى.","nishanini orundighandin kéyin, u küchlük qanaet héssiyatini hés qildi."]],"潮汛":[["潮汛对渔业活动影响很大。","سۇ ئېقىمى بېلىقچىلىق پائالىيىتىگە چوڭ تەسىر كۆرسىتىدۇ.","su éqimi béliqchiliq paaliyitige chong tesir körsitidu."]],"涧水":[["涧水清澈，适合饮用。","جىلغا سۈيى تۇپ-تۇنۇق بولۇپ، ئىچىشكە ماس كېلىدۇ.","jilgha süyi tup-tunuq bolup, ichishke mas kélidu."]],"澡身浴德":[["古人讲究澡身浴德，修身养性。","قەدىمكىلەر بەدەننى يۇيۇش ۋە ئەخلاقنى پاكلاشقا ئەھمىيەت بەرگەن.","qedimkiler bedenni yuyush we exlaqni paklashqa ehmiyet bergen."]],"渗滤":[["渗滤液需经过处理后才能排放。","سىڭىپ چىققان سۇيۇقلۇقنى بىر تەرەپ قىلغاندىن كېيىن ئاندىن تاشلاش كېرەك.","singip chiqqan suyuqluqni bir terep qilghandin kéyin andin tashlash kérek."]],"滴管":[["用滴管吸取少量试剂。","تامچە ئالمىسى بىلەن ئازغىنە رېئاكتىپ ئېلىڭ.","tamche almisi bilen azghine réaktip éling."]],"溅洒":[["液体从高处落下时会四处溅洒。","سۇيۇقلۇق يۇقىرى يەردىن چۈشكەندە تەرەپ-تەرەپكە چاچرايدۇ.","suyuqluq yuqiri yerdin chüshkende terep-terepke chachraydu."]],"滤网":[["用滤网过滤掉水中的颗粒物。","سۈزگۈچ تور بىلەن سۇدىكى زەررىچىلەرنى سۈزۈپ چىقىڭ.","süzgüch tor bilen sudiki zerrichilerni süzüp chiqing."]],"沥干":[["把衣服挂在阳台上慢慢沥干水分。","كىيىمنى بالكونغا ئېسىپ سۇنى ئاستا تامىزىڭ.","kiyimni balkongha ésip suni asta tamizing."]],"激励机制":[["公司建立了完善的激励机制。","شىركەت مۇكەممەل رىغبەتلەندۈرۈش مېخانىزمىنى قۇردى.","shirket mukemmel righbetlendürüsh méxanizmini qurdi."]],"火车票":[["他提前买好了火车票。","ئۇ پويىز بېلىتىنى ئالدىن سېتىۋالغان.","u poyiz bélitini aldin sétiwalghan."]],"炳耀":[["星光炳耀夜空。","يۇلتۇز نۇرى كېچە ئاسمىنىنى پارلىتىدۇ.","yultuz nuri kéche asminini parlitidu."]],"澧水":[["澧水是一条贯穿湖南的重要河流。","لىشۇي خۇنەندىن ئۆتىدىغان مۇھىم بىر دەريا.","lishuy xunendin ötidighan muhim bir derya."]],"澳大利亚洲":[["澳大利亚洲是南半球最大的国家。","ئاۋسترالىيە قىتئەسى جەنۇبىي يېرىم شاردىكى ئەڭ چوڭ دۆلەت.","awstraliye qit'esi jenubiy yérim shardiki eng chong dölet."]],"澳大利亚首都特区":[["澳大利亚首都特区是联邦政府的所在地。","ئاۋسترالىيە پايتەخت ئالاھىدە رايونى فېدېراتسىيە ھۆكۈمىتىنىڭ جايلاشقان جايى.","awstraliye paytext alahide rayoni fédératsiye hökümitining jaylashqan jayi."]],"乌兹别克":[["乌兹别克是中亚的一个国家。","ئۆزبېك ئوتتۇرا ئاسىيادىكى بىر دۆلەت.","özbék ottura asiyadiki bir dölet."]],"乌兹别克人":[["乌兹别克人主要居住在中亚地区。","ئۆزبېكلەر ئاساسلىقى ئوتتۇرا ئاسىيا رايونىدا ياشايدۇ.","özbékler asasliqi ottura asiya rayonida yashaydu."]],"焌油":[["焌油是一种特殊的工业用油。","قىزىق ياغ مەخسۇس بىر خىل سانائەت يېغى.","qiziq yagh mexsus bir xil sanaet yéghi."]],"无条件投降":[["战争以无条件投降告终。","ئۇرۇش ھېچقانداق شەرتسىز تەسلىم بولۇش بىلەن ئاخىرلاشتى.","urush héchqandaq shertsiz teslim bolush bilen axirlashti."]],"无患子":[["无患子是一种具有药用价值的植物。","ساپون دەرىخى دورىلىق قىممەتكە ئىگە ئۆسۈملۈك.","sapon derixi doriliq qimmetke ige ösümlük."]],"无所不为":[["为了成功，他无所不为，不择手段。","مۇۋەپپەقىيەت قازىنىش ئۈچۈن، ئۇ ھەر قانداق ئىشنى قىلىدۇ، ۋاسىتىنى تاللىمايدۇ.","muweppeqiyet qazinish üchün, u her qandaq ishni qilidu, wasitini tallimaydu."]],"熨法":[["正确的熨法能保护衣物面料。","توغرا دەملەش ئۇسۇلى كىيىم-كېچەك رەختىنى قوغدايدۇ.","toghra demlesh usuli kiyim-kéchek rextini qoghdaydu."]],"焗烤":[["焗烤是一种烹饪方式，如焗烤蔬菜。","جۇكاۋ بىر تاماق تەييارلاش ئۇسۇلى، مەسىلەن جۇكاۋ كۆكتات.","jukaw bir tamaq teyyarlash usuli, mesilen jukaw köktat."]],"焚书坑儒":[["焚书坑儒是古代的一种文化迫害行为。","كىتاب كۆيدۈرۈش ۋە ئالىملارنى كۆمۈش قەدىمكى زاماندىكى بىر خىل مەدەنىيەت زۇلۇمى.","kitab köydürüsh we alimlarni kömüsh qedimki zamandiki bir xil medeniyet zulumi."]],"片假名":[["日语中的片假名用来表示外来语。","ياپون تىلىدىكى كاتاكانا چەت ئەل تىلىدىن كىرگەن سۆزلەرنى ئىپادىلەشكە ئىشلىتىلىدۇ.","yapon tilidiki katakana chet el tilidin kirgen sözlerni ipadileshke ishlitilidu."]],"特种警察":[["特种警察负责安保工作。","ئالاھىدە ساقچىلار بىخەتەرلىك قوغداش خىزمىتىگە مەسئۇل.","alahide saqchilar bixeterlik qoghdash xizmitige mes'ul."]],"狼孩":[["狼孩从小与狼群生活在一起。","بۆرە بالىسى كىچىكىدىن باشلاپ بۆرە توپى بىلەن بىللە ياشىغان.","böre balisi kichikidin bashlap böre topi bilen bille yashighan."]],"玉洁冰清":[["她的品格玉洁冰清，令人敬佩。","ئۇنىڭ ئەخلاقى قاشتېشىدەك پاك، كىشىلەرنى ھەيران قالدۇرىدۇ.","uning exlaqi qashtéshidek pak, kishilerni heyran qalduridu."]],"玩偶":[["这个玩偶做工非常精致。","بۇ قورچاقنىڭ ياسىلىشى ئىنتايىن نەپىس.","bu qorchaqning yasilishi intayin nepis."]],"玩家":[["这位玩家操作角色十分熟练。","بۇ ئويۇنچى ئارتىسى مەشغۇلات قىلىشتا ناھايىتى ماھىر.","bu oyunchi artisi meshghulat qilishta nahayiti mahir."]],"申言":[["他申言反对这种不公平的做法。","ئۇ بۇ خىل ئادىل بولمىغان ئۇسۇلغا قارشى ئىكەنلىكىنى بىلدۈردى.","u bu xil adil bolmighan usulgha qarshi ikenlikini bildürdi."]],"异形词":[["‘异形词’在语言学中很常见。","«غەلىتە شەكىللىك سۆز» تىلشۇناسلىقتا كۆپ ئۇچرايدۇ.","«ghelite shekillik söz» tilshunasliqta köp uchraydu."]],"痛恨":[["我痛恨那些破坏环境的人。","مۇھىتنى بۇزىدىغان كىشىلەرنى ئۆچ كۆرىمەن.","muhitni buzidighan kishilerni öch körimen."]],"异端":[["他的观点被视为异端。","ئۇنىڭ كۆز قارىشى بىدئەت دەپ قارالدى.","uning köz qarishi bid'et dep qaraldi."]],"白头鹤":[["白头鹤是濒危的珍稀鸟类。","ئاق باشلىق تۇرنا يوقالاش خەۋپىگە دۇچ كەلگەن كام ئۇچرايدىغان قۇشتۇر.","aq bashliq turna yoqalash xewpige duch kelgen kam uchraydighan qushtur."]],"白羊":[["今天我看到一只白羊在吃草。","بۈگۈن مەن بىر ئاق قوينىڭ ئوت يېۋاتقانلىقىنى كۆردۈم.","bügün men bir aq qoyning ot yéwatqanliqini kördüm."]],"社火":[["春节期间，社火表演热闹非凡。","باھار بايرىمى مەزگىلىدە، ئىجتىمائىي ئوتۇن-ئويۇنلىرى ئىنتايىن قىزغىن ئۆتتى.","bahar bayrimi mezgilide, ijtimaiy otun-oyunliri intayin qizghin ötti."]],"符箓":[["符箓是道教修行的重要工具。","تۇمار دائوس دىنى ئەمەلىيىتىنىڭ مۇھىم قورالى.","tumar daos dini emeliyitining muhim qorali."]],"累积剂量":[["药物累积剂量需严格监控。","دورىنىڭ توپلانما دوزىسىنى قاتتىق نازارەت قىلىش كېرەك.","dorining toplanma dozisini qattiq nazaret qilish kérek."]],"紫色花蜜鸟":[["紫色花蜜鸟正在花间觅食。","بىنەپشە گۈللۈك شېكەر قۇشى گۈللەر ئارىسىدا يەم ئىزدەۋاتىدۇ.","binepshe güllük shéker qushi güller arisida yem izdewatidu."]],"紫菜属":[["紫菜属植物生长在海中。","بىنەپشە لەۋلە ئائىلىسىدىكى ئۆسۈملۈكلەر دېڭىزدا ئۆسىدۇ.","binepshe lewle ailisidiki ösümlükler déngizda ösidu."]],"结肠":[["结肠是消化系统的部分。","يۇغان ئۈچەي ھەزىم قىلىش سىستېمىسىنىڭ بىر قىسمىدۇر.","yughan üchey hezim qilish sistémisining bir qismidur."]]};
